 َّد َعــى وكيــلُ َّ‬\n‫اهمــا يف بط ِنــه وا ُألخـ َـرى يف ظهـ ِـره؛‬\n                                           ‫إحد ُ‬\n                                              ‫ن َ‬     ‫ن نافذتـ ِ‬      ‫ني حــا َّد ٍة طعنتـ ِ‬\n                                                                                          ‫بســك ٍ‬\n‫املد َعــى علي ـ ِه وســج َنه عشـ َـر‬\n                                    ‫فقــد طلـ َـب إقام ـ َة حـ ِّـد احلَراب ـ ِة ع َلــى َّ‬ ‫لـ َـذا َ‬\n\n                                                                                                                  ‫‪70‬‬\n\f     ‫ـأن موك َلــه‬      ‫املد َعــى عليـ ِه بـ َّ‬  ‫ـأرش اجلنايـةِ‪ ،‬أقـ َّـر وكيــلُ َّ‬         ‫وإلزامــه بـ ِ‬\n                                                                                                          ‫َ‬             ‫سـ ٍ‬\n                                                                                                                       ‫ـنوات‬\n     ‫كمــا‬ ‫ـون قَ ــد طع َن ـ ُه يف ظهـ ِـره‪َ ،‬‬             ‫املدعِ ــي يف بط ِنــه وأنكـ َـر أنْ يكـ َ‬             ‫طعـ َـن َّ‬\n     ‫اطلعـ ِـت احملكمـ ُة ع َلــى شــهاد ِة الشــهو ِد وع َلــى إقرا ِر‬                     ‫أنكـ َـر دخو َلـ ُه بي َتـ ُه‪َّ .‬‬\n     ‫العــام‪ ،‬وع َلــى تقديـ ِـر ُمقـ ِّـد ِر‬          ‫الصــاد ِر يف احلـ ِّـق َ‬‫املد َعــى علي ـ ِه يف ا ُحلكـ ِـم َّ‬         ‫َّ‬\n                  ‫املدعِ ــي طعنـ ًة يف بط ِنــه‪َ ،‬‬\n     ‫كمــا أقـ َّـر‬                                              ‫املد َعــى عليـ ِه أقـ َّـر بطعـ ِـن َّ‬    ‫ـجاج‪َّ ،‬‬  ‫الشـ ِ‬     ‫ِّ‬\n     ‫الرجــو َع عـ ِـن‬     ‫ألن ُّ‬‫الحقــا ال ُيقبــلُ ؛ َّ‬    ‫ً‬       ‫ـكاره لذلـ َـك‬\n                                                                                  ‫ُ‬        ‫بطع ِنــه يف ظهــرهِ‪ ،‬وإنـ‬\n     ‫املدعِ ــي طلـ َـب إقام ـ َة‬     ‫ن غيـ ُـر مقبــولٍ ‪ ،‬وكيــلُ َّ‬               ‫ـوق اآلدمي ـ َ‬  ‫اإلقــرا ِر يف حقـ ِ‬\n     ‫ـات‬‫ألن هــذ ِه الطلبـ ِ‬       ‫املد َعــى عليـ ِه وذلـ َـك غيـ ُـر َوجيـهٍ؛ َّ‬       ‫ـجن َّ‬ ‫حـ ِّـد احلَرابـ ِة وسـ َ‬\n       ‫بحكـ ٍـم نهائـ ٍّـي‪ .‬قضـ ِـت احملكم ـ ُة بإلـ ِ‬\n     ‫ـزام‬                                                                   ‫العــام وقــدِ انت َهــى ُ‬        ‫مـ َـن احلـ ِّـق َ‬\n     ‫ـقد َر مِ ــن قِ بــل ُمقـ ِّـد ِر‬ ‫أرش اجلناي ـ ِة امل ـ ُ َّ‬            ‫املد َعــى علي ـ ِه بــأنْ يس ـل َِّم َّ‬\n                                                                   ‫للمدعِ ــي َ‬                                            ‫َّ‬\n     ‫املد َعــى علي ـ ِه با ُحلكـ ِـم‬        ‫املدعِ ــي‪ ،‬قنـ َـع َّ‬  ‫ـات َّ‬  ‫ـجاج‪ .‬وور َد ْت باقِ ــي طلبـ ِ‬         ‫الشـ ِ‬         ‫ِّ‬\n     ‫ـتئناف املوافق ـ َة ع َلــى ا ُحلكـ ِـم‪.‬‬        ‫ـررت محكم ـ ُة االسـ ِ‬             ‫املدعِ ــي‪ ،‬قـ ْ‬        ‫ـارض َّ‬‫وعـ َ‬\n\n\n\n\n     ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n     ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                          ‫مبحافظــة جــدة‪ ،‬وبنـ ً‬\n     ‫احملكمــة العامــة مبحافظــة جــدة برقــم‪ 34317863 :‬وتاريــخ‪:‬‬\n     ‫‪1434/07/10‬ه ـ املقيــدة باحملكمــة برقــم‪ 341661934 :‬وتاريــخ‪:‬‬\n     ‫‪1434/07/10‬ه ـ واملنقوضــة مــن محكمة االســتئناف مبكة املكرمة‬\n     ‫بالقــرار رقــم‪ 34/239/845 :‬يف‪1434/6/13 :‬ه ـ فإنــه يف يــوم األربعــاء‬\n     ‫املوافق ‪1434/7/19‬ه حضر ‪ ...‬سعودي اجلنسية مبوجب الهوية الوطنية‬\n     ‫رقــم‪ ........‬الوكيــل عــن‪ ........‬بصفتــه وكيـ ًـا عــن ‪ ...‬مبوجــب الوكالــة‬\n     ‫الصــادرة عــن كتابــة العــدل الثانيــة بجنــوب جــدة رقــم‪ 3376 :‬يف‪:‬‬\n\n‫‪71‬‬\n\f‫‪1433/1/23‬ه ـ واملخـ ّـول لــه فيهــا حــق املرافعــة واملدافعــة وإقامة وســماع‬\n‫الدعــوى واســتئناف األحــكام واالعتــراض عليهــا والقناعــة بهــا‪ .‬ا‪ .‬هــ‪،‬‬\n‫وحضــر حلضــوره ‪ ...‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‪........‬‬\n‫الوكيــل عــن‪ ........‬بصفتــه وكيـ ًـا عــن‪ ........‬مبوجــب الوكالــة الصادرة‬\n‫عــن كتابــة العــدل الثانيــة مبكــة رقــم‪ 34919429 :‬يف ‪1434/7/15‬ه ـ‬\n‫واملخـ ّـول لــه فيهــا حــق املرافعــة واملدافعــة وســماع الدعــوى والــرد عليهــا‬\n‫واإلقــرار واإلنــكار والطعــن يف البينــات‪ .‬ا‪.‬هــ‪ ،‬وادعــى األول قائـ ًـا‪ :‬إن‬\n‫املدعــى عليــه قــام بطعــن موكلــي بتاريــخ‪1432/04/06 :‬ه ـ فقــد دخــل‬\n‫بيــت موكلــي حتــى وصــل إلــى غرفــة نومــه وهــو نائــم يف فراشــه فقــام‬\n‫بطعنــه بســكني حــادة طعنتــن نافذتــن إحداهمــا يف بطنــه واألخــرى‬\n‫يف ظهــره‪ ،‬وبعــد أن ظــن املدعــى عليــه أن موكلــي فاضــت روحــه إثــر‬\n‫طعنتــه فـ ّـر مــن منــزل موكلــي‪ ،‬ثــم ُنقــل موكلــي إلــى املستشــفى لتلقــي‬\n‫العــاج فسـلّمه اهلل مــن املــوت‪ ،‬ومبــا أن املدعــى عليــه طعــن موكلــي يف‬\n‫مقتـ ٍـل قاصـ ًـدا إزهــاق روحــه بعــد أن اقتحــم منزلــه قهـ ًـرا‪ ،‬فإنــي أطلــب‬\n‫ثانيــا‪ :‬ســجن‬‫أول‪ :‬إقامــة حـ ّـد احلرابــة علــى املدعــى عليــه‪ً .‬‬  ‫مــا يلــي‪ً ،‬‬\n‫املدعــى عليــه عشــر ســنوات‪ .‬ثال ًثــا‪ :‬إلــزام املدعــى عليــه بــأرش اجلنايــة‪،‬‬\n‫هكــذا ادعــى‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائـ ًـا‪:‬‬\n‫مــا ذكــره املدعــي وكالــة عــن أن موكلــي قــام بتاريــخ ‪1432/4/6‬ه ـ‬\n‫بطعــن موكلــه فصحيــح‪ ،‬فقــد طعنتــه بســكني حــادة يف بطنــه فقــط‬\n‫أمــا الطعنــة الثانيــة فغيــر صحيحــة‪ ،‬ولــم يقتحــم منــزل املدعــي أصالــة‬\n‫بــل إنــه دعانــى موكلــي لبيتــه ـ إثــر مشــكلة بينــه وبــن زوجتــه التــي‬\n‫هــي ابنــة املدعــي أصالــة ـ حملاولــة الصلــح‪ ،‬واحتــدم النقــاش بينهــم فقــام‬\n‫املدعــي أصالــة بضــرب موكلــي فأخــذ موكلــي ســكي ًنا وطعنــه طعنــة‬\n\n\n                                                                                       ‫‪72‬‬\n\f     ‫دفاعــا عــن نفســه‪ ،‬وأطلــب رد دعــوى املدعــي وإخــاء‬     ‫واحــدة يف بطنــه ً‬\n     ‫ســبيلي منهــا‪ ،‬هكــذا أجــاب‪ .‬وبســؤال املدعــي وكالــة عــن بينتــه أجــاب‬\n     ‫قائل‪ :‬بينتي شــهادة الشــهود املثبتة يف الصك املنقوض‪ ،‬هكذا أجاب‪.‬‬                 ‫ً‬\n     ‫فجــرى اطالعنــا عليهــا وهــذا نصهــا‪( :‬أحضــر املدعــي وكالــة للشــهادة‬\n     ‫كل مــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪........‬‬  ‫وأدائهــا ًّ‬\n     ‫وهــو مــن مواليــد عــام‪1371 :‬ه ـ ومتقاعــد مــن ‪ ،........‬وهــو واملدعــي مــن‬\n     ‫نفــس القبيلــة‪ ،‬وشــهد قائـ ًـا‪ :‬أشــهد بــاهلل العظيــم أنــه يف صبــاح يــوم‬\n     ‫تقريبــا وردنــي اتصــال مــن‬\n                                 ‫ً‬        ‫االعتــداء قرابــة الســاعة الثالثــة والنصــف‬\n     ‫املدعــى عليــه يخبرنــي فيــه بــأن املدعــي منعــه مــن زوجتــه فأفهمتــه بعــدم‬\n     ‫عالقتــي باألمــر‪ ،‬فاتصــل مــرة أخــرى وقــال لــي‪ :‬ســأفقدك ‪( ....‬املدعــي)‬\n     ‫ثــم أغلــق الهاتــف‪ ،‬ويف وقــت الضحــى علمــت باعتــداء املدعــى عليــه علــى‬\n     ‫املدعــي‪ ،‬هكــذا شــهد‪ .‬و[أحضــر] ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم‪ ...‬وهــو مــن مواليــد عــام‪1405 :‬ه ـ ويعمــل يف شــركة ‪،...‬‬\n     ‫وهــو واملدعــي مــن نفــس القبيلــة‪ ،‬وشــهد قائـ ًـا‪ :‬أشــهد بــاهلل العظيــم أنــه‬\n     ‫يف صبــاح يــوم اجلمعــة بعــد صــاة الفجــر كنــت أنــا والشــاهد الثالــث‬\n     ‫ـويا وحضــر املدعــى عليــه بســيارة ‪ ........‬ومعــه رجــان‪ ،‬ودخــل املدعــى‬   ‫سـ ًّ‬\n     ‫عليــه بيــت املدعــي وبيــده حديــدة لــم أســتطع متييزهــا فســألنا مــن يف‬\n     ‫صراخــا مــن داخل‬\n                     ‫ً‬       ‫الســيارة عــن ســبب قدومهــم فلــم يجيبونــا‪ ،‬ثــم ســمعنا‬\n     ‫منــزل املدعــي فســارعنا نحــوه‪ ،‬وإذا باملدعــي ملطــخ بالدمــاء واملدعــى‬\n     ‫عليــه هــرب دون أن نــراه كمــا هــرب الرجــان بســيارتهما‪ ،‬هكــذا‬\n     ‫شــهد‪ .‬و[أحضــر] ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n     ‫وهــو مــن مواليــد عــام‪1407 :‬ه ـ ويعمــل يف ‪ ،........‬وهــو جــار للمدعــي‪،‬‬\n     ‫وشــهد قائـ ًـا‪ :‬أشــهد بــاهلل العظيــم أنــه يف صبــاح يــوم اجلمعــة بعــد صــاة‬\n\n\n‫‪73‬‬\n\f‫ـويا وحضــر املدعــى عليــه بســيارة‬    ‫الفجــر كنــت أنــا والشــاهد الثانــي سـ ًّ‬\n‫‪ ........‬ومعــه رجــان‪ ،‬ودخــل املدعــى عليــه بيــت املدعــي وبيــده حديــدة‬\n‫لــم أســتطع متييزهــا فســألنا مــن يف الســيارة عــن ســبب قدومهــم فلــم‬\n‫صراخــا مــن داخــل منــزل املدعــي فســارعنا نحــوه‪،‬‬  ‫ً‬      ‫يجيبونــا‪ ،‬ثــم ســمعنا‬\n‫وإذا باملدعــي ملطــخ بالدمــاء واملدعــى عليــه هــرب دون أن نــراه كمــا‬\n                          ‫هــرب الرجــان بســيارتهما‪ ،‬هكــذا شــهد)‪ .‬ا‪ .‬هــ‪.‬‬\n‫وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه وكال ـ ًة أجــاب قائـ ًـا‪:‬‬\n‫بالنســبة للشــهود فهــم مســتورو احلــال‪ ،‬وأمــا شــهادتهم فغيــر صحيحــة‪،‬‬\n‫هكــذا أجــاب‪ .‬وبســؤال املدعــي وكال ـ ًة عــن زيــادة بينــة أجــاب قائـ ًـا‪:‬‬\n‫اجلزائيــة‬\n     ‫ّ‬     ‫الصــك الصــادر علــى املدعــى عليــه يف احلــق العــام مــن احملكمــة‬\n‫بجــدة رقــم‪/11/05 :‬ج يف‪1432/12/3 :‬ه ـ فقــد تضمــن إقــرار املدعــى‬\n‫أيضــا‪ ،‬هكــذا‬  ‫ً‬       ‫عليــه بقيامــه بطعــن موكلــي يف بطنــه ويف ظهــره‬\n‫أجــاب‪ .‬وباالطــاع علــى احلكــم املرفــق علــى لفــة رقــم‪ 17 :‬وجدنــا أن‬\n‫املدعــي العــام يذكــر أن املدعــى عليــه دخــل منــزل املدعــي أصال ـ ًة‬\n‫وطعنــه بســكني طعنــات‪ ،‬إحداهمــا‪ :‬يف بطنــه‪ ،‬واألخــرى‪ :‬يف ظهــره‬\n‫وهــو مــا تســبب يف إصابتــه‪ ،‬وقــد أجــاب املدعــى عليــه بصحــة دعــوى‬\n‫املدعــي العــام جملـ ًة وتفصيـ ًـا‪ .‬ا‪ .‬هــ‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب قائـ ًـا‪ :‬قــد ذكــر ذلــك موكلــي حتــت اإلكــراه‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبســؤال املدعــي وكال ـ ًة عــن زيــادة بينــة أجــاب قائـ ًـا‪ :‬بينتــي مــا يف‬\n‫أوراق املعاملــة‪ ،‬هكــذا أجــاب‪ .‬فجــرى اطالعنــا علــى أوراق املعاملــة‬\n‫فوجدنــا أن مصــدر احلكــم املنقــوض قــد كتــب لقســم اخلبــراء لتقديــر‬\n‫األرش مبوجــب كتابــه رقــم‪ 33508783 :‬يف‪1433/5/9 :‬ه ـ فــورد‬\n‫اجلــواب وهــو مرفــق باملعاملــة علــى لفــة رقــم‪ 50 :‬ونــص احلاجــة منــه‪:‬‬\n\n\n                                                                                        ‫‪74‬‬\n\f     ‫ـرعا بثلــث‬\n               ‫(اتضــح لنــا تقديــر أرش اجلــرح الطعنــي بالبطــن مقــدر شـ ً‬\n     ‫ألفــا وثالثمائــة وثالثــة‬\n                             ‫الديــة العمــد‪ ،‬وتقــدر مببلــغ‪ :‬مائــة وثالثــة وثالثــن ً‬\n     ‫ـال وثالثــة وثالثــن هللــة)‪ .‬ا‪ .‬هــ‪ ،‬وبعــرض ذلــك علــى املدعــى‬  ‫وثالثــن ريـ ً‬\n     ‫عليــه أجــاب قائـ ًـا‪ :‬موكلــي موافــق علــى هــذا التقديــر‪ ،‬هكــذا أجــاب‪.‬‬\n     ‫كمــا جــرت الكتابــة مــن فضيلــة مصــدر احلكــم املنقــوض لقســم‬\n     ‫اخلبــراء لتقديــر أرش طعنــة الظهــر مبوجــب كتابــه رقــم‪33508783 :‬‬\n     ‫يف‪1433/9/18 :‬ه ـ فــورد اجلــواب وهــو مرفــق باملعاملــة علــى لفــة رقــم‪:‬‬\n     ‫‪ 63‬ونــص احلاجــة منــه‪( :‬وجــود إصابــة ثانيــة وهــي جــرح طعنــي بطــول‬\n     ‫‪5‬ســم فــوق منطقــة لــوح الكتــف األيســر باجتــاه منتصــف الظهــر وقريــب‬\n     ‫مــن األبهــر الصــدري بــدون حــدوث أي إصابــة بالشــريان وعــدم وجــود‬\n     ‫أي اســترواح هوائــي‪ ،‬أدى اجلــرح فقــط إلــى قطــع بالعضــات وإجــراء‬\n     ‫خياطــة طبيــة للجــرح‪ ،‬عليــه نفيــد فضيلتكــم بأنــه اتضــح أن أرش هــذه‬\n     ‫اإلصابــة تقــدر حكومــة مببلــغ تســعة آالف ريــال)‪ .‬ا‪ .‬ه ـ وبعــرض ذلــك‬\n     ‫علــى املدعــى عليــه أجــاب قائـ ًـا‪ :‬موكلــي موافــق علــى هــذا التقديــر‪،‬‬\n     ‫ـاء علــى مــا ســلف‪ ،‬وألن املدعــى عليــه أقـ ّـر بقيامــه‬ ‫هكــذا أجــاب‪ .‬فبنـ ً‬\n     ‫بطعــن املدعــي أصال ـ ًة طعنــة واحــدة يف بطنــه‪ ،‬وأنكــر قيامــه بطعنــه‬\n     ‫طعن ـ ًة ثانيــة يف ظهــره وكــذا أنكــر دخولــه ملنزلــه‪ ،‬وأقــام املدعــي‬\n     ‫وكالـ ًة بينــة تؤيــد دعــواه‪ ،‬وهــي‪ :‬إقــرار املدعــى عليــه املثبــت على الصك‬\n     ‫اجلزائيــة مبحافظــة جــدة رقــم‪/11/05 :‬ج يف‬   ‫ّ‬        ‫الصــادر عــن احملكمــة‬\n     ‫‪1432/12/3‬ه ـ واملتضمــن‪ :‬أن املدعــي العــام يذكــر أن املدعــى عليــه‬\n     ‫دخــل منــزل املدعــي أصالــة وطعنــه بســكني طعنــات‪ ،‬إحداهمــا‪ :‬يف‬\n     ‫بطنــه‪ ،‬واألخــرى‪ :‬يف ظهــره ممــا تســبب يف إصابتــه‪ ،‬وقــد أقـ ّـر املدعــى‬\n     ‫عليــه بصحــة دعــوى املدعــي العــام جملــة وتفصيـ ًـا‪ .‬ا‪ .‬ه ـ وألنــه ال عــذر‬\n\n\n‫‪75‬‬\n\f‫ملــن أقـ ّـر‪ ،‬بــل ال إنــه ال يقبــل الرجــوع عــن اإلقــرار يف حقــوق اآلدميــن‪،‬‬\n‫واستئناســا مبــا جــاء يف‬\n                    ‫ً‬        ‫ـرعية‪( :‬املــرء مؤاخــذ بإقــراره)‪،‬‬\n                                                               ‫وللقاعــدة الشـ ّ‬\n‫شــهادة الشــهود املرصــودة أعــاه‪ ،‬وألن املدعــي وكال ـ ًة طالــب بإقامــة‬\n‫حـ ّـد احلرابــة وبتعزيــر املدعــى عليــه بالســجن مــدة عشــر ســنوات‪ ،‬وطلبــه‬\n‫إقامــة احلــد ـ علــى فــرض حتقــق شــروطه ـ وكــذا التعزيــر بالســجن طلــب‬\n‫غيــر وجيــه؛ ألن هــذه الطلبــات مــن احلــق العــام وقــد انتهــى احلــق العــام‬\n‫مبوجــب احلكــم املنـ ّـوه عنــه أعــاه‪ ،‬واألصــل أن القضيــة إذا فصــل فيهــا‬\n‫فــا يعــاد نظرهــا مــرة أخــرى‪ ،‬أمــا احلــق اخلــاص فليــس لــه إال القصــاص‬\n‫أو التعويــض‪ ،‬والقصــاص ال يســتحقه؛ ألن املدعــي وكالـ ًة لــم يطلبــه‪،‬‬\n‫وعلــى فــرض طلبــه فــإن شــروط القصــاص لــم تتحقــق‪ ،‬ينضــاف لذلــك‬\n‫أن احلكــم باجلــزاء يف احلــق اخلــاص إمنــا ي ّتجــه مبــا ليــس فيــه قصــاص‬\n‫وال ديــة كاللطمــة ومــا يف حكمهــا‪ ،‬أمــا مــا فيــه قصــاص أو ديــة فــا‬\n‫جــزاء يف احلــق اخلــاص؛ لعمــوم قــول ـ صلــى اهلل عليــه وســلم ـ‪( :‬ومــن قتــل‬\n‫لــه قتيــل فهــو بخيــر النظريــن إمــا أن يــودي وإمــا أن يقــاد)‪ ،‬فجعــل ـ عليــه‬\n‫الصــاة والســام ـ اخليــرة بــن العفــو أو القصــاص ولــم يذكــر جــزاء‪،‬‬\n‫كمــا أن الفقهــاء لــم يذكــروا تخييــر املجنــي عليــه بــن حقــه يف التعزيــر‬\n‫أو األرش يف اجلراحــات‪ ،‬ويؤيــد مــا قررتــه مــا ذكــره العالمــة محمــد بــن‬\n‫صالــح بــن عثيمــن ـ رحمــه اهلل ـ يف كتابــه املنتقــى مــن فرائــد الفوائــد‬\n‫قصاصــا‬\n      ‫ً‬      ‫ص‪( :164‬وأمــا إن كانــت اجلنايــة عمـ ًـدا فهــذه إن أوجبــت‬\n‫أو ديــة مقــدرة أو حكومــة فليــس فيهــا ســوى مــا توجبــه اجلنايــة‪ ،‬وال‬\n‫يضمــن اجلانــي ســوى ذلــك ألن الشــارع أوجــب ذلــك يف مقابلــة مــا فــات‬\n‫مــن عضــو أو منفعة)‪.‬ا‪.‬ه ـ وألن الطعنــة التــي يف بطــن املدعــي أصال ـ ًة‬\n‫قـ ّـدرت علــى أنهــا جائفــة ـ حســب القــرار املرصــود أعــاه‪ ،‬واجلائفــة فيهــا‬\n\n\n                                                                                        ‫‪76‬‬\n\f     ‫ألفــا وثالثمائــة وثالثــة‬    ‫ثلــث ديــة العمــد وقدرهــا‪ :‬مئــة وثالثــة وثالثــون ً‬\n     ‫ـال وثالثــة وثالثــون هللــة‪ .‬وألن الطعنــة التــي يف ظهــر املدعــي‬    ‫وثالثــون ريـ ً‬\n     ‫أصال ـ ًة قـ ّـدرت مــن مقــدري الشــجاج ـ حســب القــرار املرصــود أعــاه ـ‬\n     ‫بأنهــا حكومــة وقدرهــا‪ :‬تســعة آالف ريــال؛ لذلــك كلــه فقــد أعلمــت‬\n     ‫املدعــي وكال ـ ًة بــأن موكلــه ال يســتحق ســوى أرش اجلنايــة‪ ،‬ورددت‬\n     ‫باقــي طلباتــه‪ ،‬وأمــرت املدعــى عليــه‪ :‬أن يس ـلِّم للمدعــي أصال ـ ًة مبل ًغــا‬\n     ‫ـال وثالثــة‬   ‫ألفــا وثالثمائــة وثالثــة وثالثــون ريـ ً‬\n                                                            ‫قــدره‪ :‬مئــة واثنــان وأربعــون ً‬\n     ‫وثالثــون هللــة‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر املدعــى عليــه‬\n     ‫ـتعد‬\n      ‫قناعتــه باحلكــم‪ ،‬أمــا املدعــي وكال ـ ًة فقــرر عــدم القناعــة واسـ ّ‬\n     ‫اعتراضيــة‪ ،‬فجــرى تســليمه نســخة مــن احلكــم‪ ،‬وأفهمتــه‬     ‫ّ‬         ‫بتقــدمي الئحــة‬\n     ‫ـارا مــن هــذا‬    ‫يومــا اعتبـ ً‬\n                                   ‫بــأن لــه احلــق يف تقــدمي اعتراضــه خــال ثالثــن ً‬\n     ‫حقــه يف‬ ‫اليــوم‪ ،‬وإذا انتهــت املـ ّـدة احملــددة ولــم يقــدم الئحتــه ســقط ّ‬\n     ‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬   ‫ّ‬      ‫االعتــراض واكتســب احلكــم‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف‪1434/07/9 :‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ ..‬ويف يــوم الثالثــاء املوافــق ‪1434/11/18‬ه ـ‬\n     ‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار الدائــرة‬\n     ‫اجلزائيــة الثالثــة رقــم‪ 34346840 :‬يف ‪1434/11/2‬ه‪ ،‬ونــص احلاجــة‬\n     ‫منــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت‬\n     ‫املوافقــة علــى احلكــم)‪ .‬ا‪ .‬هــ‪ .‬وللبيــان جــرى إثباتــه‪ ،‬وأمــرت بإحلــاق ذلــك‬\n     ‫علــى الصــك والســجل‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف‪1434/11/18 :‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد‪ ..‬ويف يــوم اإلثنــن املوافق‪1434/11/24‬ه ـ‬\n     ‫حضــر املدعــي وكالـ ًة ‪ ...‬وحضــر حلضــوره املدعــى عليــه وكالـ ًة املثبــت‬\n\n\n‫‪77‬‬\n\f‫حضورهمــا يف جلســة ســابقة‪ ،‬ثــم ســلم املدعــى عليــه وكال ـ ًة املبلــغ‬\n‫احملكــوم بــه للمدعــي‪ ،‬وذلــك مبوجــب الشــيك املصــريف املســحوب‬\n‫علــى مصــرف ‪ ...‬برقــم ‪ 244474‬يف ‪1434/11/23‬ه ـ وقــدره مائــة‬\n‫ـال ألمــر‪ ،‬ثــم قــرر‬‫ألفــا وثالثمائــة وأربعــة وثالثــون ريـ ً‬\n                                                              ‫واثنــان وأربعــون ً‬\n‫املدعــي وكال ـ ًة قائـ ًـا‪ :‬لقــد اســتلمت كامــل املبلــغ احملكــوم بــه‬\n‫ملوكلــي بباطــن هــذا الصــك‪ ،‬ولــم تعــد لــي أي مطالبــة فيمــا يخــص‬\n‫هــذه الدعــوى‪ ،‬هكــذا قــرر فجــرى منــا االطــاع علــى وكالــة املدعــي‬\n‫ـاء عليــه ثبــت لــدي هــذا اإلقــرار‬\n                                     ‫تخولــه حــق االســتالم‪ ،‬وبنـ ً‬\n                                                                  ‫فوجدناهــا ّ‬\n‫وبذلــك تصبــح الدعــوى منتهيــة‪ .‬وللبيــان جــرى إثباتــه وأمــرت بإحلــاق‬\n‫ذلــك علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف ‪1434/11/24‬هــ‪.‬‬\n\n\n\n\n                                                                                     ‫‪78‬‬\n\f79\n\f80\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":66,"source_page_end":80,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"96bffecc62950452e5f36920c3436954520ad2392b199dfb22cb057a7c36dbaa","normalized_text_hash":"e179220185aaee949077dfff010555dfbf662edc832c287acfc89ddeab62f9dd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p66-3410235"},{"id":"863db4bc-8fad-5f7b-ba8a-b90fa2d81920","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بيت املال -مطالبة املدعي بتسليم مبلغ فسخ نكاح مودع بيت املال -مطالبة املتداخل باملبلغ بحجة أنه مقابل أتعاب -حلف املدعي اليمن على عدم اإلتفاق على التداخل -عدم ثبوت بينة املتداخل -إقرار بيت املال باملبلغ -احلكم بدفع املبلغ للمدعي .","document_number":"34231206","case_number":"344423","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/20","year":"1434","subject":"مطالبة بيت املال -مطالبة املدعي بتسليم مبلغ فسخ نكاح مودع بيت املال -مطالبة املتداخل باملبلغ بحجة أنه مقابل أتعاب -حلف املدعي اليمن على عدم اإلتفاق على التداخل -عدم ثبوت بينة املتداخل -إقرار بيت املال باملبلغ -احلكم بدفع املبلغ للمدعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/6/20 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34231206 :‬‬\n                          ‫َر ْق ُم الدعوى‪344423 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 34386020‬تاريخه‪1434/12/24 :‬هـ‬\n\n\n     ‫مطالبــة بيــت املــال‪ -‬مطالبــة املدعــي بتســليم مبلــغ فســخ نــكاح مــودع‬\n     ‫بيــت املــال‪ -‬مطالبــة املتداخــل باملبلــغ بحجــة أنــه مقابــل أتعــاب‪ -‬حلــف‬\n     ‫املدعــي اليمــن علــى عــدم اإلتفــاق علــى التداخــل‪ -‬عــدم ثبــوت بينــة‬\n         ‫املتداخــل‪ -‬إقــرار بيــت املــال باملبلــغ‪ -‬احلكــم بدفــع املبلــغ للمدعــي ‪.‬‬\n\n\n\n\n     ‫‪ .1‬قــول النبــي صلــى اهلل عليــه وســلم (مــن حلــف علــى ميــن وهــو فيــه‬\n         ‫فاجــر ليقتطــع بــه مــال امــرئ مســلم لقــي اهلل وهــو عليــه غضبــان)‪.‬‬\n     ‫‪ .2‬املــادة الســابعة مــن نظــام املرافعــات الشــرعية والفقــرة احلاديــة عشــر‬\n                                                         ‫مــن الالئحــة التنفيذيــة‪.‬‬\n     ‫‪ .3‬املــادة ‪ 181‬مــن نظــام املرافعــات الشــرعية والفقــرة ‪1‬مــن الالئحــة‬\n                                                                        ‫التنفيذ يــة‪.‬‬\n                                ‫‪ .4‬املادة رقم ‪ 179‬من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n     ‫أقــام رجــل دعــوى علــى بيــت املــال يطالــب عــوض اخللــع الــذي أودعتــه‬\n     ‫زوجتــه الســابقة يف بيــت املــال مقابــل طالقها‪-‬جــرت الكتابــة لبيــت‬\n     ‫املــال لالستفســار عــن املبلــغ املــودع ورد خطــاب بوجــود املبلــغ املذكــور‬\n     ‫باســم املدعــي وأقــر منــدوب بيــت املــال بوجــود مبلــغ اخللــع وقــرر أنــه ال‬\n\n‫‪81‬‬\n\f‫مانــع لديــه مــن تســليم املبلــغ إذا صــدر بذلــك حكــم شــرعي وأثنــاء‬\n‫نظــر احملكمــة لهــذه الدعــوى تقــدم شــخص يدعــى أنــه كان وكيــا‬\n‫للمدعــي يف دعــوى اخللــع الــذي أودع ثمنــه يف بيــت املــال وأنــه اتفــق مــع‬\n‫املدعــى علــى أن يكــون ثمــن اخللــع للوكيــل مقابــل أتعابــه وأجــرة لعملــه‬\n‫يف تلــك الدعــوى‪ ،‬أنكــر املدعــي دعــوى املتداخــل فطلبــت احملكمــة‬\n‫مــن املتداخــل البينــة فقــال ال بينــة لــي فأفهــم أن لــه ميــن املدعــي علــى‬\n‫نفــي مــا ادعــاه فطلــب اليمــن فحلــف املدعــي ولــم يحضــر املتداخــل‬\n‫فأســقطت احملكمــة حقــه يف ســماع اليمــن ألنــه تبلــغ يف موعــد أداءهــا‬\n‫ولــم يحضــر وإلقــرار بيــت املــال بوجــود املبلــغ لصالــح املدعــي ولعــدم‬\n‫البينــة للمتداخــل علــى أن املبلــغ املدعــى بــه لــه وليمــن املدعــي علــى نفــي‬\n‫دعــوى املتداخــل لــذا فقــد حكمــت احملكمــة علــى بيــت املــال بدفــع‬\n                   ‫املبلــغ املدعــى بــه‪ ،‬قنــع املدعــى عليــه‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة ‪ ..........‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة املســاعد وتاريــخ ‪ 1434/01/04‬ه ـ‬\n‫املقيــدة باحملكمــة وتاريــخ ‪1434/1/14‬ه ـ ففــي يــوم األحــد املوافــق‬\n‫‪1434/05/05‬ه ـ حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقــم ‪ ..........‬الوكيــل عــن مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة باملدينــة املنــورة يف ‪1433/12/25‬ه ـ واملخــول‬\n‫لــه فيهــا حــق اقامــة الدعــاوى واملرافعــة واملدافعــة واالقــرار واالنــكار‬\n‫والصلــح والتنــازل واالبــراء وحضــر حلضــوره‪ ،‬بصفتــه مديــر بيــت مــال‬\n\n                                                                                        ‫‪82‬‬\n\f     ‫احملكمــة العامــة بجــدة‪ ،‬وادعــى األول قائــا انــه مت ايــداع شــيك باســم‬\n     ‫موكلــي مــن قبــل املــرأة وذلــك مقابــل عــوض اخللــع أطلــب الــزام بيــت‬\n     ‫املــال باحملكمــة العامــة بجــدة بتســليم مبلغــا ملوكلــي هكــذا ادعــى‬\n     ‫وبعــرض ذلــك أجــاب قائــا كل مــا ذكــره املدعــي وكالــة صحيــح وال‬\n     ‫مانــع مــن تســليم املدعــي أصالــة كامــل املبلــغ املذكــور اذا صدر حكم‬\n     ‫علــى بيــت املــال بتســليمه هكــذا أجــاب وقــد جــرت الكتابــة منــا لبيــت‬\n     ‫املــال باحملكمــة العامــة بجــدة مبوجــب كتابنــا يف ‪1434/1/11‬ه ـ‬\n     ‫لالستفســار عــن املبلــغ املذكــور فوردنــا اجلــواب يف ‪1434/1/18‬ه ـ‬\n     ‫ونــص احلاجــة منــه‪( :‬عليــه نفيــد فضيلتكــم بأنــه حتــت يــد بيــت املــال‬\n     ‫مبلــغ فســخ نــكاح واملودعــة مــن املــرأة حيــث مت ايــداع املبلــغ بحســاب‬\n     ‫بيــت املــال لــدى مؤسســة النقــد العربــي الســعودي مبوجــب منــوذج االيــداع‬\n     ‫يف ‪1433/7/29‬هـ ومت اصدار ايصال االستالم يف ‪1433/8/4‬هـورصد‬\n     ‫املبلــغ اعــاه بالدفاتــر املاليــة) ا‪.‬ه ـ عنــد ذلــك حضــر ســعودي اجلنســية‬\n     ‫مبوجــب الهويــة الوطنيــة وقــرر قائــا‪ :‬أن ســبب املبلــغ املدعــى بــه الــذي‬\n     ‫ذكــره املدعــي وكالــة يف هــذه الدعــوى عــوض خلــع مــن زوجــة املدعــي‬\n     ‫أصالــة وهــو كامــل املهــر الــذي ســلمه لهــا وقــد ترافعــت انــا يف قضيــة‬\n     ‫اخللــع واتفقــت مــع املدعــي أصالــة أن أجــور اتعابــي هــي عــوض اخللــع مــن‬\n     ‫زوجتــه ‪ ...‬وقــدره خمســون الــف ريــال‪ ،‬وقــد تكلفــت يف هــذه القضيــة‬\n     ‫تكاليــف ماليــة باهضــه مــن أجــرة ســكن وســفر وأجــور معقبــن وغيــر‬\n     ‫ذلــك‪ ،‬أطلــب اثبــات أن املبلــغ املدعــى بــه قيمــة أتعابــي يف قضيــة اخللــع‬\n     ‫مــع زوجــة املدعــي أصالــة والــزام بيــت املــال بتســليمه لــي هكــذا قــرر‬\n     ‫وبنــاء علــى املــادة اخلامســة والســبعون فقــد اذنــت بدخولــه يف الدعــوى‬\n     ‫وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائــا‪ :‬ادفــع بدفــع شــكلي‬\n\n\n‫‪83‬‬\n\f‫وهــو أن مــكان اقامــة املدعــي أصالــة يف املدينــة النبويــة وإذا كان‬\n‫يطالــب بأتعــاب محامــاة فاملتداخــل يف هــذه الدعــوى يقيــم دعــواه يف‬\n‫احملكمــة العامــة باملدينــة هكــذا أجــاب‪ .‬عنــد ذلــك أفهمــت املتداخــل‬\n‫باإلجابــة علــى موضــوع دعــوى املتداخــل فأجــاب قائــا‪ :‬مــا ذكــره‬\n‫املتداخــل أصالــة غيــر صحيــح‪ ،‬فلــم يترافــع عــن موكلــي يف قضيــة‬\n‫اخللــع ولــم يتفــق معــه علــى أي مبلــغ‪ ،‬وأطلــب رد دعــوى املتداخــل وإخــاء‬\n‫ســبيلي منهــا‪ ،‬هكــذا أجــاب‪ .‬وبســؤال التداخــل أصالــة عــن بينتــه‬\n‫أجــاب قائــا‪ :‬ليــس لــدي بينــة وأطلــب ميــن املدعــي أصالــة علــى نفــي‬\n‫دعــواي‪ ،‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة أجــاب‬\n‫قائــا‪ :‬موكلــي مســتعد بــأداء اليمــن‪ ،‬وأطلــب اســتخالف احملكمــة‬\n‫العامــة باملدينــة لســماع ميــن موكلــي‪ ،‬هكــذا أجــاب‪ .‬عنــد ذلــك قــررت‬\n‫اســتخالف رئيــس احملكمــة العامــة باملدينــة املنــورة أو مــن ينيــب لســماع‬\n‫ميــن املدعــي أصالــة بحضــور املتداخــل أصالــة بهــذه الصيغــة‪( :‬أقســم‬\n‫بــاهلل العظيــم أننــي لــم أتفــق مــع املتداخــل‪ :‬أن يترافــع عنــي يف قضيــة‬\n‫اخللــع مــع زوجتــي ســابقا ‪ .....‬ولــم أتفــق معــه أن األتعــاب يف هــذه القضيــة‪.‬‬\n‫ويف يــوم اإلثنــن املوافــق‪1434/06/05 :‬ه ـ حضــر املدعــي وكالــة ‪،‬‬\n‫وحضــر حلضــوره ‪ ،‬بصفتــه مديــر بيــت مــال احملكمــة العامــة‪ ،‬املثبــت‬\n‫حضورهمــا يف جلســة ســابقة‪ ،‬كمــا حضــر املدعــي أصالــة‪،..........‬‬\n‫بريطانــي اجلنســية مبوجــب رخصــة اإلقامــة ولــم يحضــر املتداخــل‬\n‫أصالــة‪ ، ..........‬وال مــن ينــوب عنــه رغــم تبليغــه مبوعــد هــذه اجللســة‬\n‫حســب توقيعــه علــى ضبــط اجللســة الســابقة‪ ،‬ثــم جــرى منــا عــرض‬\n‫اليمــن علــى املدعــي أصالــة بعــد تذكيــره بخطرهــا وبقــول النبــي ـ‬\n‫صلــى اهلل عليــه وســلم ـ ‪( :‬مــن حلــف علــى ميــن هــو فيهــا فاجــر ليقتطــع‬\n\n\n                                                                                        ‫‪84‬‬\n\f     ‫بهــا مــال امــرئ مســلم لقــي اهلل وهــو عليــه غضبــان) رواه مســلم‪،‬‬\n     ‫فاســتعد باحللــف فأذنــت لــه فحلــف قائــا‪( :‬أقســم بــاهلل العظيــم أننــي‬\n     ‫لــم أتفــق مــع املتداخــل يف هــذه الدعــوى‪ :‬أن يترافــع عنــي يف قضيــة‬\n     ‫اخللــع مــع زوجتــي ســابقا أتفــق معــه أن األتعــاب يف هــذه القضيــة)‪،‬‬\n     ‫هكــذا حلــف‪ .‬فبنــاء علــى مــا ســلف‪ ،‬وألن املتداخــل يف هــذه الدعــوى‬\n     ‫قــد تغيــب عــن اجللســة بعــد علمــه بهــا‪ ،‬وتخلفــه عنهــا ـ مــع علمــه بهــا ـ‬\n     ‫يســقط حقــه يف ســماع اليمــن‪ ،‬وألنــه ال بينــة للمتداخــل يف دعــواه‪ ،‬وألن‬\n     ‫املدعــي أصالــة قــد حلــف علــى نفــي دعــوى املتداخــل يف هــذه الدعــوى‪،‬‬\n     ‫وبنــاء علــى إفــادة بيــت املــال يف ‪1434/1/18‬ه ـ املرصــودة يف اجللســة‬\n     ‫الســابقة‪ ،‬واملتضمنــة‪( :‬أنــه حتــت يــد بيــت املــال مبلــغ وقــدره خمســون‬\n     ‫الــف ريــال فســخ نــكاح واملودعــة مــن املــرأة)‪ .‬ا‪ .‬ه ـ لذلــك كلــه فقــد‬\n     ‫أمــرت بيــت املــال باحملكمــة العامــة مبحافظــة جــدة بتســليم مبلغــا‬\n     ‫للمدعــي أصالــة‪ ، :‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر املدعــي‬\n     ‫أصالــة ومديــر بيــت املــال قناعتهمــا باحلكــم‪ ،‬أمــا املتداخــل أصالــة‬\n     ‫ســوف يبلــغ باحلكــم ولــه االعتــراض بطلــب االســتئناف خــال ثالثــن‬\n     ‫يوم ـ ًا اعتبــار ًا مــن تاريــخ تبليغــه بنســخة احلكــم‪ ،‬وإذا تأخــر عــن هــذه‬\n     ‫املـ ّـدة ـ مــع تبلغــه لشــخصه بنســخة احلكــم ســقط حقــه يف االعتــراض‬\n     ‫القطعيــة ألن احلكــم علــى بيــت‬\n                                     ‫ّ‬      ‫بطلــب االســتئناف واكتســب احلكــم‬\n     ‫املــال ـ يف هــذه الواقعــة ـ ال يســتأنف وفقــا للمــادة التاســعة والســبعون‬\n     ‫بعــد املائــة مــن نظــام املرافعــات الشــرعية‪ ،‬وإذا تب َّلــغ املتداخــل يف هــذه‬\n     ‫الدعــوى لغيــر شــخصه ولــم يقـ ِّـدم اعتراضــه رفــع احلكــم االســتئناف‬\n     ‫مــن دون اعتــراض‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/06/05 :‬هــ‪.‬‬\n\n\n‫‪85‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثاء املوافــق ‪1434/10/06‬هـ عادت‬\n‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار الدائــرة احلقوقيــة‬\n‫اخلامســة يف ‪1434/9/6‬هـ ونص احلاجة منه‪( :‬وبدراســة احلكم وصورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــرر اعــادة املعاملــة إلــى ناظرهــا ملالحظة‬\n‫أن فضيلتــه لــم يطلــع علــى صــك احلكــم وهــل اكتســب القطعيــة أم ال‬\n‫قبــل احلكــم للمدعــي بتســليمه املبلــغ املذكــور مــن بيــت املــال والتأكــد‬\n‫مــن أن نظــر هــذه القضيــة مــن اختصاصــه أم ال اعمــاال للمــادة ‪7/11‬‬\n‫مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة واعمــال املــادة‬\n‫‪ 1/181‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ومــا ذكــره‬\n‫يف شــرحه علــى الالئحــة االعتراضيــة مــن قلــة ورق الضبــط غيــر وجيــه‬\n‫كمــا أن املعتــرض ذكــر يف الئحتــه االعتراضيــة مــا ينبغــي مناقشــته‬\n‫بحضــور الطرفــن واجــراء الــازم نحــوه وخاصــة الفقــرة الثانيــة) ا‪.‬ه ـ‬\n‫عليــه أجيــب أصحــاب الفضيلــة وفقهــم اهلل فأقــول جــرى اطالعــي علــى‬\n‫صــك احلكــم الصــادر مــن ســلفي يف ‪1433/7/28‬ه ـ واملتضمــن‪ :‬فســخ‬\n‫نــكاح املدعيــة وقــد انتهــى احلكــم بقناعــة الطرفــن علمــا بأننــا اطلعنــا‬\n‫عليــه ســابقا وســقط رصــده ســهوا وأمــا عــن إعمــال املــادة ‪ 1/181‬مــن‬\n‫نظــام املرافعــات فقــد أجبــت عنهــا يف ضبــط القضيــة‪ .‬أمــا عــن الفقــرة‬\n‫الثانيــة مــن الالئحــة اإلعتراضيــة فقــد أمــرت بتحديــد موعــد حــن‬\n‫مراجعــة املدعــي‪ .‬ويف يــوم اإلثنــن املوافــق ‪1434/11/10‬ه ـ حضــر‬\n‫املدعــي وكالــة‪ :‬املثبــت حضــوره يف جلســة ســابقة‪ ،‬ولــم يحضــر منــدوب‬\n‫بيــت املــال باحملكمــة العاملــة ـ وهــو قانــع باحلكــم املثبــت يف اجللســة‬\n‫الســابقة‪ ،‬ولــم يحضــر املتداخــل أصالــة‪ :‬وال مــن ينــوب عنــه رغــم تبلغــه‬\n‫مبوعــد هــذه اجللســة حســب احملضــر املرفــق باملعاملــة‪ ،‬ثــم قــرر املدعــي‬\n\n\n                                                                                   ‫‪86‬‬\n\f     ‫وكالــة قائــا‪ :‬إن املتداخــل أصالــة يريــد مضــارة موكلــي ومماطلتــه‬\n     ‫عــن اســتيفاء حقــه‪ ،‬وقــد وعدنــي مــرار أن يحضــر للمحكمــة ألجــل‬\n     ‫اإلجابــة علــى قــرار محكمــة االســتئناف املرصــود يف جلســة ســابقة‬\n     ‫بــدون موعــد لكنــه يخلفنــي‪ ،‬هكــذا قــرر‪ .‬ونظــرا ألن الفقــرة الثانيــة‬\n     ‫مــن الئحــة اعتــراض املتداخــل تضمنــت أنــه لديــه شــاهد‪ ،‬ونظــرا ألن‬\n     ‫عــدم حضــوره يعــد مماطلــة ولــددا وتشويشــا‪ ،‬ونظــرا ألن العــرف جــار‬\n     ‫أن مــن لديــه بينــة ال يتخلــف عــن مجلــس احلكــم‪ ،‬لذلــك كلــه فإنــي مــا‬\n     ‫زلــت بــاق علــى مــا حكمــت بــه وأجريتــه‪ .‬وللبيــان جــرى إثباتــه‪ ،‬وأمــرت‬\n     ‫بإحلــاق ذلــك علــى الصــك والســجل ومــن ثــم رفــع كافــة أوراق املعاملــة‬\n     ‫حملكمــة االســتئناف حســب التعليمــات‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/11/10 :‬هـ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد‪ ،‬ففــي يــوم األحــد املوافــق‪1435/01/28 :‬ه ـ‬\n     ‫عــادت املعاملــة مــن محكمــة اإلســتئناف وبرفقها قــرار الدائرة احلقوقية‬\n     ‫اخلامســة يف‪1434/12/24 :‬ه ـ ونــص احلاجــة منــه (وبدراســة احلكــم‬\n     ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد‬\n     ‫االجــراء األخيــر) ‪.‬ا‪.‬ه ـ وللبيــان جــرى اثباتــه وأمــرت بإحلــاق ذلــك علــى‬\n     ‫الصــك والســجل ‪ .‬وبــاهلل التوفيــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1435/1/28‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n     ‫قضــاة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n     ‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n     ‫مــن فضيلــة الشــيخ ‪ ..........‬القاضــي باحملكمــة العامــة بجــدة تاريــخ‬\n     ‫‪1434/6/5‬ه ـ املتضمــن دعــوى ضــد بيــت املــال باحملكمــة العامــة‪،‬‬\n\n\n‫‪87‬‬\n\f‫احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم وص ــورة‬\n‫ضبط ــه والئحتــه االعتراضيــة تق ــرر املوافق ــة عل ــى احلكــم بعــد االجــراء‬\n‫االخير وباهلل التوفيق وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه‬\n                                                                           ‫وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪88‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":81,"source_page_end":88,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5aca3bdbdcfbe41d7bd7e3345af8cf20c35c08d1322839cc9f187af88644691f","normalized_text_hash":"786aeaf05ee231c930e8a14e2fd08e87174e1ee0f66fcee7528ef0b7cf6b8275","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p81-34231206"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

