SELECT 'moj-all-verified-judgments-review-002-chunk-035' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"2b78c1f9-1412-5177-9503-e38f6fa22800","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -اختناق بدخان أدى إلى وفاة قاصر -مطالبة الولي املدعى عليه بدية ابنه -تعذر الصلح بن الطرفن -عجز عن إثبات الدعوى -عدم قبول املدعي مين املدعى عليه بنفي الدعوى -رد الدعوى -استحقاق املدعي ليمن خصمه على نفي الدعوى متى","document_number":"34306831","case_number":"34171722","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة يف حائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/25","year":"1434","subject":"دية -اختناق بدخان أدى إلى وفاة قاصر -مطالبة الولي املدعى عليه بدية ابنه -تعذر الصلح بن الطرفن -عجز عن إثبات الدعوى -عدم قبول املدعي مين املدعى عليه بنفي الدعوى -رد الدعوى -استحقاق املدعي ليمن خصمه على نفي الدعوى متى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/25 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34306831 :‬‬\n                         ‫َر ْق ُم الدعوى‪34171722 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34340472‬تاريخه‪1434/10/26 :‬ه‬\n\n\n      ‫ديــة‪ -‬اختنــاق بدخــان أدى إلــى وفــاة قاصــر‪ -‬مطالبــة الولــي املدعــى‬\n      ‫عليــه بديــة ابنــه‪ -‬تعــذر الصلــح بــن الطرفــن‪ -‬عجــز عــن إثبــات‬\n      ‫الدعــوى‪ -‬عــدم قبــول املدعــي ميــن املدعــى عليــه بنفــي الدعــوى ‪ -‬رد‬\n      ‫الدعــوى‪ -‬اســتحقاق املدعــي ليمــن خصمــه علــى نفــي الدعــوى متــى‬\n                                                                        ‫طلبهــا‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬لــو يعطــى النــاس بدعواهــم‬\n      ‫الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن علــى املدعــى عليــه)‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                                                 ‫علــى مــن أنكــر)‪.‬‬\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه تســبب يف وفــاة ابنــه بعــد أن اختنــق أثناء‬\n      ‫نومــه لديــه مــن آثــار رائحــة الفحــم‪ ،‬ولــذا فقــد طلــب إلزامــه بتســليمه‬\n      ‫نصيبــه مــن ديــة ابنــه‪ ،‬أقــر املدعــى عليــه بوفــاة ابــن املدعــي أثنــاء وجــوده‬\n      ‫لديــه ودفــع بأنــه لــم يتســبب يف ذلــك وإمنــا قــام بإشــعال فحــم للتدفئــة‬\n      ‫فتعرضــا لالختنــاق بالدخــان املنبعــث منــه‪ ،‬طلبــت احملكمــة مــن‬\n      ‫املدعــي بينــة علــى مــا جــاء يف دعــواه فقــرر أنــه ال بينــة لديــه ولــم يقبــل‬\n\n‫‪321‬‬\n\f‫ميــن خصمــه علــى نفــي دعــواه بعــد أن اســتعد ببذلهــا‪ ،‬املدعــي ال توجــد‬\n‫لديــه بينــة تفيــد بتســبب املدعــى عليــه بوفــاة مورثــه‪ ،‬قضــت احملكمــة‬\n‫بســقوط دعــوى املدعــي ضــد املدعــى عليــه‪ ،‬وأفهمــت املدعــي بــأن لــه‬\n‫ميــن املدعــى عليــه علــى نفــي دعــواه متــى مــا أراد‪ ،‬قنــع املدعــى عليــه‬\n‫باحلكــم وعــارض املدعــي‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                      ‫احلكــم‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...............‬رئيــس احملكمــة اجلزائيــة‬\n‫املكلــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 34171722‬وتاريــخ‬\n‫‪1434/04/14‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34137286‬وتاريــخ‬\n‫‪1434/1/17‬ه ففــي يــوم االثنــن املوافــق‪ 1434/05/13‬ه ـ افتتحــت‬\n‫اجللســة يف متــام الســاعة الواحــدة وأربعــون دقيقــة وفيهــا حضــر‪...............‬‬\n‫ســعودي بالســجل رقــم (‪ )...............‬وادعــى علــى احلاضــر‪...............‬‬\n‫ســعودي بالســجل رقــم (‪ )...............‬قائــا يف حتريــر دعــواه عليــه ‪ :‬أن‬\n‫هــذا احلاضــر معــي تســبب يف وفــاة ابنــي حيــث أخــذه بــدون أذن منــي مــع‬\n‫وجــود فــارق الســن الكبيــر بــن ابنــي وبــن املدعــى عليــه حيــث إن ابنــي‬\n‫يــدرس يف املرحلــة املتوســطة ( ثانــي متوســط ) ولــم يبــت خــارج املنــزل‬\n‫ســوى تلــك الليلــة ‪ ،‬وحيــث إن املدعــى عليــه هــو مــن تســبب يف وفاتــه‬\n‫حيــث مــات مختنقــا مــن آثــار رائحــة الفحــم أطلــب نصيبــي مــن ديــة ابنــي‬\n‫وهــو مبلــغ وقــدره مائتــن وخمســن ألــف ريالـ ـ ــ‪ 250000‬ـ ــ‪ ،‬هــذه دعــواي‬\n‫وأســأله اجلــواب ‪ .‬وبعــرض دعــوى املدعــى عليــه أجــاب بقولــه ‪ :‬إن ابنه ‪.....‬‬\n‫رحمــه اهلل ـ كان صديقــا لــي وكان يأتينــي يف منزلــي كثيــرا ويأتينــي‬\n\n                                                                                       ‫‪322‬‬\n\f      ‫علــى ســيارة ـ دايــو ـ ويف تلــك الليلــة كان زارنــي يف االســتراحة وقمنــا‬\n      ‫بإشــعال فحــم ألن اجلــو كان بــاردا وقمنــا بعــد العشــاء باجللــوس ثــم منــت‬\n      ‫ولــم أفــق إال يف الصبــاح وقمــت باالتصــال علــى الهــال األحمــر حينمــا‬\n      ‫رأيــت ‪ ...............‬ســاقطا عنــد بــاب املجلــس وقــد تعرضنــا فيمــا يبــدوا‬\n      ‫لالختنــاق وهــذا قضــاء اهلل وقــدره وليــس لــي فيــه يــد حيــث كــدت أن‬\n      ‫أختنــق معــه لكــن اهلل ســلم ‪ ،‬وليــس بينــي وبــن‪ ...............‬رحمــه اهلل‬\n      ‫أي خــاف وال عــداوة ولــم يكــن ينــوي املبيــت تلــك الليلــة عنــدي ولكــن‬\n      ‫فيمــا يبــدوا أننــا تعرضنــا لالختنــاق وحــدث مــا حــدث ‪ .‬هكــذا أجــاب ‪.‬‬\n      ‫وللتأمــل رفعــت اجللســة وعليــه جــرى التوقيــع ‪ .‬ويف جلســة أخــرى حضــر‬\n      ‫املدعــي واملدعــى عليــه ثــم ســألت املدعــي هــل لديــك بينــة علــى دعــواك ؟‬\n      ‫فأجــاب بقولــه ‪ :‬ال‪ .‬فســألت املدعــي هــل ترضــى ميــن املدعــى عليــه علــى‬\n      ‫نفــي دعــواك ؟ فأجــاب بقولــه ‪ :‬ال‪ .‬ثــم ســألت املدعــى عليــه هــل حتلــف‬\n      ‫علــى نفــي دعــوى املدعــي فأجــاب بقولــه ‪ :‬نعــم ‪ .‬ثــم عرضــت اليمــن‬\n      ‫التاليــة علــى املدعــى عليــه ( واهلل العظيــم الــذي ال إلــه إال هــو عالم الغيب‬\n      ‫والشــهادة أن مــا جــاء يف دعــوى املدعــي غيــر صحيــح ‪ .‬ولــم أتســبب يف‬\n      ‫وفــاة ابــن املدعــى عليــه ) وبعــرض ذلــك علــى املدعــى عليــه قــال أحلــف‬\n      ‫علــى صــدق إن شــاء اهلل فحذرتــه مــن اليمــن ومغبتهــا وعظمهــا عنــد‬\n      ‫اهلل فقــال أحلــف ‪ .‬ثــم جــرى االطــاع علــى صــك حصــر الورثــة رقــم (‬\n      ‫‪ )34241938‬وتاريخ ‪1434/6/14‬هـ واملتضمن وفاة يف ‪1434/2/18‬هـ‬\n      ‫وانحصــار ورثتــه يف والــده املدعــي ووالدتــه‪ ،‬والصــادر مــن احملكمــة‬\n      ‫العامــة يف حائــل ‪ ،‬ثــم جــرى االطــاع منــي علــى القــرار الشــرعي الصــادر‬\n      ‫بهــذه القضيــة والصــادر مــن فضيلــة القاضــي الشــيخ رئيــس احملكمــة‬\n      ‫اجلزائيــة ســابقا املتضمــن (جلــده ســتون جلــدة لقــاء اتهــام املدعــى عليــه‬\n\n\n‫‪323‬‬\n\f‫بحيــازة املســكر ) املصــدق مــن محكمــة االســتئناف مبوجــب القــرار‬\n‫رقــم ( ‪ )33423427‬ثــم جــرى عــرض الصلــح بــن الطرفــن فلــم اســتطع‬\n‫ـاء علــى مــا‬\n             ‫التوصــل إلــى ذلــك وقــد تكــرر ذلــك يف عــدة جلســات فبنـ ً‬\n‫ســلف مــن الدعــوى واإلجابــة وحيــث ال توجــد للمدعــي أي بينــه ضــد‬\n‫املدعــى عليــه فيمــا يذكــر وحيــث اســتعد املدعــى عليــه ببــذل اليمــن‬\n‫علــى نفــي دعــوى املدعــي ولعــدم رضــا املدعــي ميــن املدعــى عليــه علــى‬\n‫نفــي دعــواه‪ ،‬وال يوجــد ضــد املدعــى عليــه أي قرينــة أو بينة تفيد بتســببه‬\n‫بوفــاة مــورث املدعــي ‪ ،‬ولقولــه صلــى اهلل عليــه وســلم فيمــا أخرجــه‬\n‫الشــيخان مــن حديــث ابــن عبــاس ‪-‬رضــي اهلل عنهما‪-‬قال‪(:‬لــو يعطــى‬\n‫النــاس بدعواهــم الدعــى نــاس دمــاء رجــال وأموالهــم ولكــن اليمــن‬\n‫علــى املدعــى عليــه) ولروايــة البيهقــي ( البينــة علــى املدعــي واليمــن علــى‬\n‫مــن أنكــر) لذلــك كلــه فقــد حكمــت بســقوط دعــوى املدعــي ضــد‬\n‫املدعــى عليــه ‪،‬وأفهمــت املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي‬\n‫دعــواه متــى مــا أراد وبذلــك حكمــت وبعرضــه علــى املدعــي لــم يقنــع بــه‬\n‫وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة فجــرى تســليمه‬\n‫صــورة مــن الصــك الشــرعي إلبــداء معارضتــه عليــه يف مــدة أقصاهــا‬\n‫ثالثــون يومــا مــن هــذا اليــوم اخلميــس املوافــق ‪1434/8/25‬ه ـ وأنــه إن‬\n‫تأخــر عــن ذلــك ســقط حقــه يف االعتــراض وســترفع املعاملــة حملكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة ففهــم ذلــك ‪ ،‬وبعرضــه علــى املدعــى‬\n‫عليــه قنــع بــه ‪ ،‬وعليــه جــرى التوقيــع‪ ،‬واهلل املوفــق وصلــى اهلل وســلم‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/8/25‬ه ـ ‪.‬‬\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34340472‬وتاريــخ‬\n                                                           ‫‪1434/10/26‬هـ‬\n\n\n                                                                                      ‫‪324‬‬\n\f325\n\f                      ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n         ‫قتل أحدِ املقيمني من قِ َبل زميله ‪ ،‬بطعنه عدة‬\n          ‫طعنات وهو نائم ‪ ،‬ومطالبة إقامة حدِ الغيلة‬\n  ‫‪5‬‬                                                        ‫قتل‬     ‫‪1‬‬\n         ‫عليه‪ .‬دافع املدعى عليه مبرضه وحاالت اجلنون‬\n                           ‫التي تنتابه‬\n\n\n         ‫شروع مواطن يف قتل أخيه بإطالق عدة طلقات‬\n          ‫نارية عليه ‪ ،‬حيث وجد ملقيا على الرصيف‬\n  ‫‪20‬‬                                                       ‫قتل‬     ‫‪2‬‬\n         ‫متهما أخاه ‪ .‬دافع املدعى عليه باإلنكار‪ ،‬وأنه‬\n                  ‫كان خارج مدينة احلادث‬\n\n\n            ‫وجه‬\n             ‫قتل مواطن على يد ابن عمه‪ ،‬حيث ّ‬\n  ‫‪34‬‬     ‫السالح إليه فانطلقت رصاصة يف صدره‪ .‬ودافع‬          ‫قتل‬     ‫‪3‬‬\n                  ‫املدعى عليه بأنه كان ميازحه‬\n\n\n            ‫ضربا بسطلٍ‬\n                    ‫ً‬     ‫قتل مواطن على يد أخته ‪،‬‬\n             ‫حديدي على رأسه ‪ .‬أقرت املدعى عليها‬\n  ‫‪42‬‬                                                       ‫قتل‬     ‫‪4‬‬\n         ‫بالضرب ‪ ،‬ودافع الوكيل بأن اجلرح سطحي ‪،‬‬\n                   ‫والوفاة بسبب مرضه املزمن‬\n\n\n          ‫قتل مواطنة على يد شقيقها؛ إذ أطلق عليها‬\n  ‫‪58‬‬      ‫شكا يف عالقة بينها وبني رجل‪،‬‬\n                                     ‫الرصاص ّ‬              ‫قتل‬     ‫‪5‬‬\n          ‫ودافع مبرضه النفسي‪ ،‬ومعاناته من الصرع‬\n\n\n         