                               ‫ـزام َّ‬ ‫ا َّلتــي حل َِقـ ْـت بابـ ِـن موك ِلــه‪ ،‬وإلـ َ‬\n‫املد َعــى عليـ ِه‬   ‫فيمــا لـ ْـم يحضـ ِـر َّ‬  ‫الدعـ َـوى َ‬    ‫ـاء يف َّ‬             ‫املد َعــى عليـ ِه الثَّا ِنــي َ‬\n                                                                              ‫مبــا جـ َ‬                           ‫َّ‬\n‫األولُ مـ َـع أ َّن ـ ُه ُتبل ـ َغ مبوعــدِ اجللس ـةِ‪ ،‬اطلعـ ِـت احملكم ـ ُة ع َلــى محضـ ِـر‬\n\n                                                                                                                           ‫‪52‬‬\n\f     ‫ـررت الكتابـ َة‬‫ـات‪ ،‬وقـ ِ‬      ‫مقومِ ــي احلكومـ ِ‬     ‫اللجنـ ِة املروريـةِ‪ ،‬ومحضـ ِـر جلنـ ِة ِّ‬\n     ‫ـات حسـ َـب التقديـ ِـر اجلديــدِ ‪،‬‬        ‫الديـ ِ‬\n                                                     ‫ـجاج إلعــاد ِة تقديـ ِـر َ‬  ‫الشـ ِ‬    ‫إلــى ُمقـ ِّـد ِر ِّ‬\n       ‫كلُّ‬‫عليهمــا بــأنْ يدفـ َـع ُ‬\n                                  ‫َ‬            ‫املد َعــى‬\n                                                       ‫ـزام َّ‬\n                                                           ‫ضوريــا بإلـ ِ‬‫ًّ‬     ‫قضـ ِـت احملكم ـ ُة ُح‬\n     ‫ـببا ب َهــا حسـ َـب‬‫أرش اإلصابـ ِة ا َّلتــي تسـ َ‬   ‫نصيبـ ُه مِ ــن ِ‬\n                                                                       ‫َ‬        ‫للمدعِ ــي‬\n                                                                                      ‫واحــدٍ من ُهمــا َّ‬\n     ‫ـاب احملكم ـ ِة‬    ‫ـظ املبلـ ِـغ يف حسـ ِ‬                ‫عليهمــا‪ ،‬وقـ ْ‬\n                                                      ‫ـررت حفـ َ‬              ‫َ‬          ‫النســب ِة املقــرر ِة‬\n            ‫ـتئناف املوافقـ َة ع َلــى احل ْ‬\n     ‫ُكـ ِـم‪.‬‬                              ‫ـررت محكمـ ُة االسـ ِ‬            ‫للقاصريـ َـن‪ ،‬قـ ْ‬    ‫املوحــدِ َ‬\n\n\n\n\n     ‫العامــة‬\n        ‫ّ‬      ‫احلمــد هلل وحــده وبعــد‪ ،‬فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n     ‫باألحســاء حضــر‪ ....‬ســعودي بالســجل املدنــي رقــم ‪....‬بالوكالــة عــن‬\n     ‫وليــا علــى ‪ ...‬مبوجــب الوكالــة الصــادرة عــن كتابــة عــدل‬      ‫بصفتــه ًّ‬\n     ‫عفيــف برقــم ‪ 2280/44‬بتاريــخ ‪1430/2/13‬ه ـ وحضــر حلضــوره ‪....‬‬\n     ‫ســعودي بالســجل املدنــي رقــم ‪ ....‬و‪ .....‬ســعودي بالســجل املدنــي رقــم ‪....‬‬\n     ‫وبســؤال املدعــي عــن دعــواه تبــن أن دعــواه غيــر محــررة‪ ،‬ويف جلســة‬\n     ‫أخــرى حضــر املدعــي وكالـ ًة كمــا حضــر املدعــى عليــه ‪ ....‬ولــم يحضــر‬\n     ‫املدعــى عليــه الثانــي‪ ،‬وبســؤال املدعــي عــن دعــواه أجــاب قائـ ًـا إنــه يف‬\n     ‫راكبا بصحبة‬  ‫ً‬      ‫يــوم الثالثــاء املوافــق ‪1429/4/23‬هـ كان ابــن موكلي‬\n     ‫املدعــى عليــه يف ســيارته نــوع ‪ ........‬صنــع ســنة ‪1997‬م وأثنــاء ســيرهم‬\n     ‫يف طريــق ‪ ........‬وقــع حــادث تصــادم بــن ســيارة ‪ ........‬وكانــت بقيادتــه‬\n     ‫وبــن ســيارة نــوع ‪ ........‬صنــع ســنة ‪2006‬م بقيــادة املدعــى عليــه‪ ،‬وقــد‬\n     ‫أديــن املدعــى عليــه األول باخلطــأ بنســبة ‪ %75‬وأديــن املدعــى عليــه الثانــي‬\n     ‫باخلطــأ بنســبة ‪ %25‬وقــد نتــج عــن احلــادث إصابــات يف ابــن موكلــي‬\n     ‫املدعــى عليــه إصابــات بليغــة يف رأســه وباقــي أجــزاء جســمه‪ ،‬أطلــب‬\n\n‫‪53‬‬\n\f‫تقديــر اإلصابــات والتــي حلقــت بــه وإلــزام املدعــى عليهمــا بدفــع أرش‬\n‫اإلصابــات؛ هــذه دعــواي‪ .‬وبعــرض الدعــوى علــى املدعــي عليــه قــال مــا‬\n‫ذكــره املدعــي يف دعــواه كلــه صحيــح‪ ،‬ومــا ذكــر مــن تقديــر اخلطــأ‬\n‫علـ َّـي بنســبة ‪ %25‬مــن قبــل املــرور صحيــح‪ ،‬وأنــا مقتنــع بــه وليــس لــدي‬\n‫أي اعتــراض عليــه؛ هكــذا أجــاب‪ .‬وقــد جــرى االطــاع علــى محضــر‬\n‫جلنــة مقومــي احلكومــات باحملكمــة العامــة بالريــاض رقــم ‪356/32‬‬\n‫وتاريــخ ‪1432/5/29‬ه ـ لفــة ‪ 9‬املتضمــن بعــد املقدمــة مــا نصــه‪( :‬وبعــد‬\n‫االطــاع علــى املعاملــة ومراجعــة التقريــر الطبــي ومبشــاهدة املصــاب‬\n‫ـرعا بثلــث الديــة‬\n                  ‫فقــد تبــن ثقــب يف اجلمجمــة قدرنــاه دامغــة مقــدرة شـ ً‬\n‫بثالثــة وثالثــن ألف ـ ًا وثالثمائــة وثالثــة وثالثــن ريــا ًال وثلــث الريــال‬\n‫ـرعا‪ ،‬وآثــار نــدب جراحيــة علــى البطــن ونســبة العجــز‬   ‫(‪ )333331/3‬شـ ً‬\n‫‪ %2‬مــن اجلســم قدرنــاه بألفــي ريــال (‪ )2000‬حكومــة خــذل األطــراف‬\n‫العلويــة ونســبة العجــز ‪ %65‬مــن اجلســم قدرنــاه بخمســة وســتني ألــف ريال‬\n‫(‪ )65000‬حكومــة‪ ،‬وخــذل األطــراف الســفلية ونســبة العجــز ‪%58‬‬\n‫مــن اجلســم قدرنــاه بثمانيــة وخمســن ألــف ريــال حكومــة‪ ،‬وتيبســات‬\n‫مفصليــة شــديدة ونســبة العجــز ‪ %38‬مــن اجلســم قدرنــاه بثمانيــة وثالثــن‬\n‫ألــف ريــال (‪ )38000‬حكومــة‪ ،‬وفقــدان التحكــم بالبول ونســبة العجز‬\n‫ـرعا‪ ،‬وعــدم التحكــم‬     ‫‪ %100‬قدرنــاه مبئــة ألــف ريــال (‪ )100000‬شـ ً‬\n‫بالبــراز ونســبة العجــز ‪ %100‬قدرنــاه مبئــة ألــف ريــال (‪)100000‬‬\n‫ـرعا‪ ،‬وفقــدان القــدرة اجلنســية ونســبة العجــز ‪ %100‬قدرنــاه مبئــة‬      ‫شـ ً‬\n‫ـرعا‪ ،‬وتأثــر اإلدراك والتركيــز ونســبة‬       ‫ألــف ريــال (‪ )100000‬شـ ً‬\n‫العجــز ‪ %35‬مــن اجلســم وقدرنــاه بخمســة وثالثــن ألــف ريــال (‪)35000‬‬\n‫حكومــة‪ ،‬ونوبــات تشــنجية ونســبة العجــز ‪ %14‬مــن اجلســم قدرناهــا‬\n\n\n                                                                                     ‫‪54‬‬\n\f     ‫بأربعــة عشــر ألــف ريــال (‪ )14000‬حكومــة ‪.‬ا‪.‬هــ‪ ،‬كمــا جــرى االطــاع‬\n     ‫علــى القــرار الشــرعي الصــادر عــن احملكمــة اجلزئيــة باألحســاء رقــم‬\n     ‫‪/1001‬ض‪ 8/68‬وتاريــخ ‪1431/3/25‬ه ـ املتضمــن إدانــة املدعــى عليــه‬\n     ‫بنســبة ‪ %75‬وإدانــة املدعــى عليــه بنســبة ‪ %25‬جتــاه احلــادث‪ ،‬كمــا جــرى‬\n     ‫االطــاع علــى محضــر اجتمــاع اللجنــة املروريــة الدائمــة رقــم ‪/2177‬م‬\n     ‫ض‪1‬وتاريــخ ‪1429/7/6‬ه ـ لفــة ‪ 28‬املتضمــن إدانــة قائــد املركبة الثانية‬\n     ‫باخلطــأ بنســبة ‪%75‬؛ وذلــك لألســباب التاليــة ‪ -1‬االنحــراف املفاجئ دون‬\n     ‫التأكــد مــن خلــو الطريــق‪ -2 .‬عــدم أخــذ احليطــة واحلــذر أثنــاء القيــادة‪،‬‬\n     ‫ويــدان قائــد املركبــة األولــى باخلطــأ بنســبة ‪%25‬؛ وذلــك لألســباب‬       ‫ُ‬\n     ‫التاليــة‪ -1 :‬مباشــرة الصــدم مبقدمــة الســيارة‪ -2 .‬وعــدم تفاديــه وقــوع‬\n     ‫احلــادث‪ ،‬وكانــت قــد جــرت الكتابــة إلــى مقــدر الشــجاج يف هــذه‬\n     ‫احملكمــة برقــم ‪ 32954831‬وتاريــخ ‪1433/3/13‬ه لإلفــادة عــن الديــة‬\n     ‫حســب التقديــر اجلديــد‪ ،‬فوردنــا اجلــواب برقــم ‪ 32954831‬وتاريــخ‬\n     ‫‪1433/3/22‬ه ـ املتضمــن أن الديــات بالتقديــر اجلديــد تكــون مليون ـ ًا‬\n     ‫ـال وتســعة‬ ‫وســتمائة وخمســة وثالثــن ألــف وتســعمائة وتســعة وتســعني ريـ ً‬\n     ‫هلــات ‪ 1,635,999,9‬ثــم جــرى االطــاع علــى صــك الواليــة الصــادر‬\n     ‫عــن هــذه احملكمــة رقــم ‪ 5/10‬وتاريــخ ‪1430/1/21‬ه ـ املتضمــن إقامــة‬\n     ‫‪ ..‬وليــا علــى ابنــه‪ ،‬كمــا جــرى االطــاع علــى الوكالــة الصــادرة عــن‬\n     ‫كتابــة عــدل عفيــف رقــم ‪ 2280/44‬وتاريــخ ‪1430/2/13‬ه ـ املتضمنــة‬\n     ‫وليــا علــى ابنــه مبوجــب صــك‬    ‫وكالــة املدعــي احلاضــر عــن بصفتــه ًّ‬\n     ‫ـاء علــى مــا تقــدم مــن‬‫الواليــة رقــم ‪ 5/10‬وتاريــخ ‪1430/1/21‬ه ـ فبنـ ً‬\n     ‫الدعــوى واإلجابــة‪ ،‬وحيــث أديــن املدعــى عليــه األول باخلطــأ بنســبة‬\n     ‫‪ ،%75‬وأديــن املدعــى عليــه الثانــي باخلطــأ بنســبة ‪ %25‬وصــادق علــى‬\n\n\n‫‪55‬‬\n\f‫صحــة حتديــد النســبة‪ ،‬وألن املدعــى عليــه قــد حضــر اجللســة األولــى‬\n‫ـاء علــى األمــر الســامي‬  ‫و ُتبلـ َـغ مبوعــد اجللســة بعدهــا ولــم يحضــر‪ ،‬وبنـ ً‬\n‫الكــرمي رقــم ‪ 43108‬وتاريــخ ‪1432/10/2‬ه ـ املتضمــن زيــادة ديــة اخلطــأ‬\n‫وأن هــذا التقديــر يســري علــى كل حالــة لــم يحكــم فيهــا قبــل العمــل‬\n‫أول‪ /‬إلــزام املدعــى عليــه األول بدفــع مبلــغ‬  ‫بــه فقــد قــررت مــا يلــي‪ً :‬‬\n‫ألفــا وتســعمائة وتســعة وتســعون‬  ‫وقــدره مليــون ومائتــان وســتة وعشــرون ً‬\n‫ثانيــا‪/‬‬\n     ‫ـال واثنتــان وتســعون هللــة ‪ 1226999.92‬للمدعــي أصال ـ ًة‪ً .‬‬           ‫ريـ ً‬\n‫إلــزام املدعــى عليــه الثانــي بدفــع مبلــغ وقــدره أربعمائــة وثمانيــة آالف‬\n‫ـال وســبعة وتســعون هللــة‪408999.97‬‬       ‫وتســعمائة وتســعة وتســعون ريـ ً‬\n‫ـاء علــى املــادة اخلامســة‬\n                           ‫للمدعــي أصال ـ ًة املذكــور‪ ،‬وبــه حكمــت‪ .‬وبنـ ً‬\n‫واخلمســن مــن نظــام املرافعــات الشــرعية فــإن احلكــم يف حــق املدعــى‬\n‫حضوريــا وســيتم تســليم املدعــى عليهمــا نســخة مــن احلكــم‬\n                                                           ‫ًّ‬       ‫عليهمــا يعــد‬\n‫يومــا مــن تاريــخ تبليغهمــا‬\n                             ‫لتقــدمي الئحتهمــا االعتراضيــة خــال ثالثــن ً‬\n‫باحلكــم وإال يســقط حقهمــا يف االعتــراض‪ ،‬ويكتســب احلكــم‬\n‫القطعيــة إن لــم يتقدمــا بشــيء وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n              ‫محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف ‪1433/4/11‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬ففــي يــوم األحــد املوافق‪1433/08/04‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10:45‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب رقــم ‪33/1045249‬‬\n‫مرفقــا بهــا قــرار دائــرة األحــوال الشــخصية‬‫ً‬     ‫وتاريــخ ‪1433/7/20‬ه ـ‬\n‫األولــى رقــم ‪ 33340245‬وتاريــخ ‪1433/7/14‬ه ـ املتضمــن بعــد املقدمــة‬\n‫مــا نصــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫أول‪ /‬جــاء يف أول الصــك أن احلاضــر‬     ‫وأوراق املعاملــة لوحــظ مــا يلــي‪ً :‬‬\n\n\n                                                                                        ‫‪56‬‬\n\f     ‫بالوكالــة عــن ‪ ...‬وهــذا غيــر صحيــح لكــون املذكــور مولــى عليــه‬\n     ‫مبوجــب صــك الواليــة رقــم ‪ 5/10‬وتاريــخ ‪1430/1/21‬هــ‪ ،‬ويتعــن‬\n     ‫ثانيــا‪ /‬لــم يبــن فضيلــة القاضــي يف الصــك‬    ‫تصحيــح مــا يلــزم يف ذلــك‪ً .‬‬\n     ‫صفــة قصــور املولــى عليــه؛ هــل هــو قصــور عقلــي أو غيــره‪ .‬وال بــد مــن‬\n     ‫ذلــك فعلــى فضيلتــه مالحظــة مــا أشــير إليــه وإحلــاق مــا يجــد يف الصــك‬\n     ‫وجوابــا‬\n        ‫ً‬      ‫وضبطــه وســجله‪ ،‬ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا) ا‪.‬ه ـ‬\n     ‫علــى مــا ذكــره أصحــاب الفضيلــة يف املالحظــة األولــى‪ /‬فــإن صحــة‬\n     ‫وليــا علــى ابنــه مبوجــب‬ ‫الوكالــة أن احلاضــر بالوكالــة عــن ‪ ...‬بصفتــه ًّ‬\n     ‫الوكالــة الصــادرة عهــن كتابــة عــدل عفيــف رقــم ‪ 2280/44‬وتاريــخ‬\n     ‫‪1430/2/13‬هــ‪ ،‬وجــرى تصحيــح ذلــك يف الصــك وضبطــه وســجله‪.‬‬\n     ‫عقليــا كمــا‬\n                 ‫ًّ‬   ‫وجوابــا علــى املالحظــة الثانيــة‪ /‬فــإن املولــى عليــه قاصــر‬\n                                                                                      ‫ً‬\n     ‫هــو موضــح يف صــك الواليــة رقــم ‪ 5/10‬وتاريــخ ‪1430/1/21‬ه ـ‬\n     ‫جوابــا علــى أصحــاب الفضيلــة‪ ،‬وبــاهلل‬    ‫ً‬    ‫املرفــق باملعاملــة‪ ،‬هــذا مــا لــزم‬\n     ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر‬\n                                                                       ‫يف ‪1433/8/4‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد‪ ،‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫باملنطقــة الشــرقية باخلطاب رقــم ‪ 331532825‬وتاريخ ‪1433/10/09‬هـ‬\n     ‫مرفقــا بهــا قــرار دائــرة األحــوال الشــخصية األولــى رقــم ‪3341393‬‬            ‫ً‬\n     ‫وتاريــخ ‪1433/09/17‬ه ـ املتضمــن بعــد املقدمــة مــا نصــه‪( :‬وباالطــاع‬\n     ‫جوابــا علــى قــرار الدائــرة املشــار إليــه‪،‬‬\n                                                ‫ً‬    ‫علــى مــا أجــراه فضيلــة القاضــي‬\n     ‫جوابــا علــى قــرار الدائــرة‬\n                               ‫ً‬       ‫لوحــظ أن مــا أحلقــه فضيلــة القاضــي بالصــك‬\n     ‫املشــار إليــه لــم يتــم إحلاقــه يف ضبــط القضيــة‪ ،‬ويتعــن إكمــال مــا‬\n     ‫وجوابــا علــى مالحظــة‬\n                           ‫ً‬        ‫يلــزم ثــم إعــادة املعاملــة إلكمــال الزمهــا) ا‪ .‬ه‪،‬‬\n\n\n‫‪57‬‬\n\f‫أصحــاب الفضيلــة فــإن اجلــواب علــى مالحظــة أصحاب الفضيلــة الواردة‬\n‫يف القــرار رقــم ‪/ 33340245‬ش‪/1‬ب يف تاريــخ ‪1433/07/14‬ه ـ كان‬\n‫قــد جــرى إحلاقــه يف الصــك وضبــط القضيــة يف اجللســة املفتتحــة يف‬\n‫يــوم األحــد املوافــق ‪1433/08/04‬ه ـ كمــا هــو مبــن يف صــورة صحيفــة‬\n‫الضبــط املصدقــة رقــم ‪ 83‬مــن مجلــد الضبــط رقــم ‪ 10/13‬حقوقــي‬\n‫جوابــا علــى أصحــاب الفضيلــة وبــاهلل‬    ‫ً‬      ‫املرفقــة باملعاملــة هــذا مــا لــزم‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر‬\n                                                                ‫يف ‪1433/10/15‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مرفقــا‬\n     ‫ً‬     ‫مبوجــب اخلطــاب رقــم ‪ 331848113‬وتاريــخ ‪1433/12/26‬ه ـ‬\n‫بهــا قــرار دائــرة األحــوال الشــخصية األولــى رقــم ‪ 33466202‬وتاريــخ‬\n‫‪1433/11/27‬ه املتضمــن بعــد املقدمــة مــا نصــه‪( :‬وباالطــاع علــى مــا‬\n‫جوابــا علــى قــرار الدائــرة املشــار إليــه لوحــظ‬‫ً‬       ‫أجــراه فضيلــة القاضــي‬\n‫أول‪ /‬أنــه جــاء يف مــا قــرره فضيلتــه ألــزم املدعــى عليــه األول‬      ‫مــا يلــي‪ً :‬‬\n‫والثانــي بتســليم املبلــغ احملكــوم بــه للمدعي أصالـ ًة‪ ،‬وهذا محل نظر ملا‬\n‫تقضــي بــه التعليمــات مــن حفــظ مبالــغ القاصريــن يف حســاب احملكمــة‬\n‫ثانيــا‪ /‬أن محــل بيــان املســتند‬\n                                 ‫املوحــد للقاصريــن واألوقــاف واملعتوهــن‪ً .‬‬\n‫يف نظــر الدعــوى مــع غيــاب املدعــى عليــه قبــل ســماعها ال بعــده ليكــون‬\n‫ـتقبل‪ .‬ثال ًثــا‪ /‬مــا جــاء يف‬\n                           ‫ـتندا يف صحــة ســماعها ملالحظــة ذلــك مسـ ً‬         ‫مسـ ً‬\n‫جوابــا‬\n   ‫ً‬      ‫جــواب فضيلتــه علــى قــرار الدائــرة األخيــر بــأن مــا أحلقــه فضيلتــه‬\n‫علــى قــرار الدائــرة كان قــد جــرى إحلاقــه يف الصــك وضبــط القضيــة‬\n‫يف جلســة يــوم األحــد ‪1433/8/4‬ه ـ فيــه إيهــام إذ لــم يبــن فضيلتــه أنــه‬\n‫جــرى إكمــال الــازم حيــال مــا جــاء يف املالحظــة؛ إذ إنــه إذا كان قــد‬\n\n\n                                                                                            ‫‪58‬‬\n\f      ‫ٍ‬\n     ‫كاف‬       ‫أحلــق مــا جــرت اإلشــارة إليــه كمــا ذكــره فضيلتــه فإن ذلــك غير‬\n     ‫يف حــال عــدم اشــتمال الصــورة الضوئيــة املرفقــة باملعاملــة عليــه واملتعــن‬\n     ‫يف اإلجابــة بعــد إحلــاق ذلــك بصــورة الضبــط الضوئيــة املرفقــة اإلشــارة‬\n     ‫ـتقبل‪ ،‬فعلــى فضيلتــه‬ ‫إلــى أنــه مت إكمــال الــازم ملالحظــة ذلــك مسـ ً‬\n     ‫مالحظــة مــا أشــير إليــه وإحلــاق مــا يجــد يف الصــك وضبطــه وســجله‪،‬‬\n     ‫ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا) ا‪.‬هــ‪ ،‬ولوجاهــة مــا ذكــره‬\n     ‫أصحــاب الفضيلــة يف املالحظــة األولــى فقــد قــررت حفــظ املبلــغ يف‬\n     ‫حســاب احملكمــة املوحــد للقاصريــن واألوقــاف واملعتوهــن مبصــرف‬\n     ‫ـتقبل‬\n        ‫‪ ....‬وســيتم مالحظــة مــا جــاء يف أصحــاب الفضيلــة الثانيــة مسـ ً‬\n     ‫وجوابــا عــن املالحظــة الثالثــة فــإن لــم يتــم اتخــاذ أي إجــراء حتــى يتــم‬\n                                                                                     ‫ً‬\n     ‫اإلشــارة إلــى أنــه مت إكمــال الــازم ومــا جــاء يف املالحظــة يف القــرار‬\n     ‫الســابق مــن أنــه لــم يتــم إحلــاق اجلــواب يف ضبــط القضيــة غيــر صحيــح‪،‬‬\n     ‫وبعــد الرجــوع إلــى املعاملــة متــت اإلجابــة علــى أصحــاب الفضيلــة بــأن‬\n     ‫اجلــواب علــى املالحظــة املذكــورة مرفــق بضبــط القضيــة وذلــك حســب‬\n     ‫الصحيفــة رقــم ‪ 83‬مــن مجلــد الضبــط رقــم ‪10/13‬املرفقــة باملعاملــة‪،‬‬\n     ‫جوابــا علــى أصحــاب الفضيلــة‪ ،‬وفقهــم اهلل‪ ،‬وبــاهلل‬       ‫ً‬       ‫هــذا مــا لــزم‬\n     ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر‬\n                                                                     ‫يف ‪1434/2/2‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد مت تصديــق احلكم من محكمة االســتئناف‬\n     ‫بالقــرار رقــم ‪ 34190519‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                         ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f‫تاريخه‪1433/9/18 :‬هـ‬\n                  ‫ُ‬  ‫الص ِّك‪33414920 :‬‬  ‫َر ْق ُم َّ‬\n                    ‫عوى‪33294168 :‬‬  ‫الد َ‬  ‫َر ْق ُم َّ‬\n     ‫ِ‬\n    ‫االستئناف‪:‬‬ ‫صديق من محكم ِة‬\n                            ‫ِ‬ ‫َر ْق ُم قرا ِر ال َّت‬\n           ‫تاريخه‪1434/1/3 :‬هـ‬\n                          ‫ُ‬      ‫‪/34606‬ق‪2‬‬\n\n\n\n       ‫ـس بســيار ٍة تسـ َّـب َب يف إصاب ـ ِة َقاص ـ ٍر‪ُ -‬مطالب ـ ُة َّ‬\n‫املد َعــى‬                                                                      ‫أرش إصاب ـةٍ‪ -‬دهـ ٌ‬‫ُ‬\n‫الدع ـ َوى‬  ‫املد َعــى علي ـ ِه ع َلــى َّ‬ ‫األرش‪ُ -‬مصادق ـ ُة َّ‬ ‫ِ‬         ‫علي ـ ِه بســدا ِد قيم ـ ِة‬\n‫للمدعِ ــي‪-‬‬\n         ‫َّ‬       ‫ودفعِ ــه بالعجـ ِز َعــن ســدا ِد املبلـ ِـغ‪ -‬إيجابيـ ُة ال َّتقريـ ِر الطبـ ِّـي‬\n‫ـوت‬\n ‫ـوق‪ -‬ثبـ ُ‬    ‫ـون َّإل بعـ َـد ثبــوتِ احلقـ ِ‬  ‫ـات اإلعســا ِر ال يكـ ُ‬ ‫ـجاج‪ -‬إثبـ ُ‬ ‫تقديـ ُـر ِشـ ٍ‬\n                 ‫أرش اإلصاب ـ ِة املقـ َّـد ِر‪.‬‬    ‫املد َعــى علي ـ ِه بتسـ ِ‬\n                                              ‫ـليم ِ‬                             ‫الدع َوى‪-‬إلــزا ُم َّ‬\n                                                                                                     ‫َّ‬\n\n\n\n\n‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                         ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫املد َعــى علي ـ ِه‬         ‫وليــا علــى ابن ـ ِه املج ِنــي علي ـ ِه بـ َّ‬\n                       ‫ـأن َّ‬                                               ‫املدعِ ــي بصف ِتــه ًّ‬   ‫ا َّد َعــى َّ‬\n‫خلف ـ ُه فنتـ َـج‬\n                ‫دون ال َّنظـ ِـر مل ـ َـن َ‬    ‫ـاء رجوعِ ــه ب َهــا َ‬   ‫بدهســه بالســيار ِة أثنـ َ‬‫ِ‬         ‫ـام‬\n                                                                                                              ‫قـ َ‬\n‫املد َعــى علي ـ ِه‬      ‫فصل ـ ٌة يف دعـ َـو ُاه‪ ،‬وقَ ــد ُأديـ َـن َّ‬‫ـات باب ِنــه ُم َّ‬‫َعــن ذلـ َـك إصابـ ٌ‬\n‫فقــد طلـ َـب ا ُحلكــم عليـ ِه بتســليمِ ه‬                          ‫بكامـ ِـل نســب ِة اخلطـ ِأ يف احلـ ِ‬\n                                                          ‫ـادث؛ لـ َـذا َ‬\n‫املد َعــى علي ـ ِه‬  ‫ـجاج‪ ،‬أقـ َّـر َّ‬ ‫الشـ ِ‬   ‫ـات املقـ َّـدر ِة مــن قِ بــل ُمقـ ِّـد ِري ِّ‬\n                                                                                               ‫أرش اإلصابـ ِ‬   ‫َ‬\n  ‫الدعـ َـوى‪ُ ،‬جملـ ًة وتفصيـ ًـا‪َّ ،‬إل أ َّنـ ُه دفـ َـع بعجـ ِـزه َعــن تسـ ِ‬\n‫ـليم‬                                                                                            ‫ـاء يف َّ‬\n                                                                                                        ‫مبــا جـ َ‬\n                                                                                                                 ‫َ‬\n‫للمدعِ ــي‪ ،‬اطلعـ ِـت احملكم ـ ُة ع َلــى ال َّتقريـ ِـر الطبـ ِّـي ال ِّنهائـ ِّـي‬          ‫هـ َـذا املبلـ ِـغ َّ‬\n‫اطلعـ ْـت ع َلــى تقديـ ِـر ُمقـ ِّـد ِر‬     ‫َ‬         ‫كمــا‬\n                                                           ‫َ‬      ‫املدعِ ــي‪،‬‬\n                                                                          ‫ـات ابـ ِـن َّ‬   ‫ـاص بإصابـ ِ‬    ‫اخلـ ِّ‬\n                                                                                                                       ‫‪60‬‬\n\f     ‫ومــا دفـ َـع‬\n                ‫الدعـ َـوى َ‬ ‫ـاء يف َّ‬           ‫املد َعــى عليـ ِه أقـ َّـر َ‬\n                                        ‫مبــا جـ َ‬                             ‫ـجاج باحملكمـةِ‪َّ ،‬‬       ‫الشـ ِ‬    ‫ِّ‬\n     ‫ـوت‬‫ـون َّإل بعـ َـد ثبـ ِ‬\n                            ‫ـات اإلعســا ِر ال يكـ ُ‬           ‫بـ ِه مـ َـن اإلعســا ِر غيـ ُـر مؤثـ ٍـر؛ ْإذ إثبـ ُ‬\n     ‫أرش اإلصاب ـ ِة‬   ‫ـليم ِ‬  ‫املد َعــى علي ـ ِه بتسـ ِ‬  ‫ـزام َّ‬‫ـوق‪ ،‬قضـ ِـت احملكم ـ ُة بإلـ ِ‬         ‫احلقـ ِ‬\n     ‫املد َعــى علي ـ ِه ع َلــى‬      ‫املدعِ ــي‪ ،‬عـ َ‬\n                                ‫ـارض َّ‬                      ‫ـجاج البـ ِـن َّ‬\n                                                                           ‫الشـ ِ‬  ‫املقـ َّـد ِر مِ ــن ُمقـ ِّـد ِر ِّ‬\n                                                         ‫ِ‬\n                 ‫ـتئناف املصا َدق ـ َة ع َلــى ا ُحلكـ ِـم‪.‬‬        ‫ـررت محكم ـ ُة االسـ‬     ‫ا ُحلكـ ِـم‪ ،‬قـ ْ‬\n\n\n\n\n     ‫فلدي أنا‬\n           ‫َّ‬     ‫احلمد هلل وحده والصالة والسالم على َمنْ ال نبي بعده‪ ،‬وبعد‪..‬‬\n     ‫ـاء علــى املعاملــة الــواردة‬\n                                ‫‪ ........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n     ‫إلينــا مــن صاحــب الفضيلــة رئيــس احملكمــة العامــة باألحســاء مبوجــب‬\n     ‫خطــاب فضيلتــه رقم‪33691909‬وتاريخ‪1433/04/25‬ه ـ واملقيــدة بهــذه‬\n     ‫احملكمــة برقــم ‪ 33799075‬وتاريــخ ‪1433/4/27‬ه ـ واحملالــة إلينــا‬\n     ‫مــن فضيلــة الرئيــس برقــم ‪ 33294168‬وتاريــخ ‪1433/04/27‬ه ـ ويف‬\n     ‫يــوم اإلثنــن ‪1433/09/18‬ه ـ افتتحــت اجللســة األولــى الســاعة احلاديــة‬\n     ‫عشــرة والنصــف‪ ،‬وفيهــا حضــر ‪ ....‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي (‪ )....‬وادعــى علــى احلاضــر معــه ‪ .....‬باكســتاني اجلنســية مبوجــب‬\n     ‫رخصــة اإلقامــة الصــادرة عــن جــوازات الهفــوف برقــم (‪ )...‬قائـ ًـا يف‬\n     ‫دعــواه‪ :‬إن هــذا احلاضــر كان يقــود ســيارة مــن نــوع ‪ ........‬ويقــوم بإيصــال‬\n     ‫املــاء احمل َّلــى لهجــرة ‪ ،........‬وقــد قــام بالرجــوع بالســيارة دون النظــر ملــن‬\n     ‫تقريبــا ممــا‬\n               ‫ً‬     ‫خلفــه ممــا أدى بــه إلــى دهــس ابنــي وعمــره ســت ســنوات‬\n     ‫أدى إلــى إصابتــه بكســر يف احلــوض وبجــرح يف الركبــة وجــرح يف‬\n     ‫الظهــر ويف الســاعد األميــن وقــد قــدرت نســبة العجــز فيــه بنســبة ‪%28‬‬\n     ‫وقــد قــدرت اإلصابــات مــن قِ بــل مقــدري الشــجاج مببلــغ قــدره اثنــان‬\n\n‫‪61‬‬\n\f‫ـال‪ ،‬وحيــث إن املدعــى عليــه هــو‬‫ألفــا وســبعمائة وخمســون ريـ ً‬  ‫وأربعــون ً‬\n‫املتســبب يف احلــادث بنســبة مائــة باملائــة فأطلــب احلكــم عليــه باملبلــغ‬\n‫املذكــور؛ هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه عــن دعــوى املدعي أجاب‬\n‫بواســطة املترجــم ‪ ...‬هنــدي اجلنســية مبوجــب رخصــة اإلقامــة الصــادرة‬\n‫عــن جــوازات الهفــوف برقــم (‪ )....‬فأجــاب قائـ ًـا‪ :‬مــا ذكــره املدعــي يف‬\n‫دعــواه مــن وقــوع حادثــة الدهــس البنــه املذكــور واإلصابــات املذكورة‪،‬‬\n‫وأرش اجلنايــة وتســببي بالنســبة الكاملــة كل ذلــك صحيــح‪ ،‬لكننــي‬\n‫علمــا بأننــي قمـ ُـت بإســعاف الطفــل؛ هكــذا‬‫ال أســتطيع دفــع هــذا املبلــغ ً‬\n‫أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي قــال‪ :‬ال أعلــم عــن حالــه شــيئًا؛‬\n‫هكــذا قــرر‪ .‬ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة‪ ،‬ومنهــا‬\n‫أصــل التقريــر الطبــي النهائــي الصــادر عــن اللجنــة الطبيــة احملليــة‬\n‫مبستشــفى امللــك فهــد بالهفــوف برقــم ‪ 41/27/4/14904‬وتاريــخ‬\n‫‪1432/11/28‬ه ـ املتضمــن أن املواطــن ‪ ...‬مصــاب بــ‪ /1 :‬كســر احلــوض‬\n‫مت شــفاؤها ‪ /2‬جــرح بازلــة خلــف الركبــة اليمنــى‬   ‫عظــم ا ِحلــق‪ %25‬وقــد َّ‬\n‫‪6‬ســم‪/3 .2‬جــرح حارصــة وســط الظهر‪10‬ســم‪ /4 . 2‬جــرح باضعــة‬\n‫يف الســاعد األميــن بطــول ‪15‬سم*‪1‬ســم =‪15‬ســم‪ ، 2‬املجموع‪31‬ســم‪2‬‬\n‫ونســبة العجــز‪ %3‬لكافــة اجلــروح ومجمــوع العجــز الكلــي‪ . %28‬أعضــاء‬\n‫اللجنــة الطبيــة‪ :‬د‪ ........ .‬استشــاري جراحــة عامــة‪ ،‬د‪ ........ .‬استشــاري‬\n‫باطنيــة املــخ واألعصــاب‪ ،‬د‪ ........ .‬استشــاري طــب التأهيــل ا‪.‬هــ‪،‬‬\n‫كمــا جــرى االطــاع علــى تقديــر مقــدر الشــجاج باحملكمــة العامــة‬\n‫باألحســاء ذي الرقــم ‪ 321583989‬والتاريــخ ‪1432/12/20‬ه ـ املتضمــن‬\n‫مــا نصــه‪« :‬بعــد االطــاع علــى التقريــر الطبــي النهائــي ُوجــد يف الطفــل‬\n‫أول‪ :‬لديــه كســر يف احلــوض وفيــه عجــز‪ %25‬فيكــون‬        ‫عــدة إصابــات‪ً ،‬‬\n\n\n                                                                                    ‫‪62‬‬\n\f     ‫ثانيــا‪ :‬جــرح‬\n                 ‫ألفــا وخمســمائة ريــال ‪ 37500‬ريــال ‪ً .‬‬      ‫فيــه ســبعة وثالثــون ً‬\n     ‫خلــف الركبــة اليمنــى فيــه ألــف وخمســمائة ريــال ‪.‬ثال ًثــا‪ :‬جــرح يف وســط‬\n     ‫رابعــا‪ :‬جــرح باضعــة يف‬‫ـال ‪750‬ريــا ًال ‪ً .‬‬‫الظهــر فيــه ســبعمائة وخمســون ريـ ً‬\n     ‫الســاعد األميــن يكــون فيــه ثالثــة آالف ريــال‪ ،‬فيكــون املجمــوع اثنــن‬\n     ‫ـال‪ ،‬ومذيــل بتوقيــع مقــدر الشــجاج‬    ‫ألفــا وســبعمائة وخمســن ريـ ً‬ ‫وأربعــن ً‬\n     ‫أن املدعــى عليــه‬‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬ومبــا َّ‬\n                                                                               ‫ا‪.‬ه ـ فبنـ ً‬\n     ‫أقـ َّـر بدعــوى املدعــي وأ َّنــه هــو املتســبب باحلــادث بالنســبة الكاملــة وأنــه‬\n     ‫قانــع مبــا ورد يف قــرار مقــدر الشــجاج‪ ،‬ودفــع بأنــه غيــر قــادر علــى دفــع‬\n     ‫أن مــا دفــع بــه غيــر مؤثــر إذ إثبــات اإلعســار ال يكــون إال‬ ‫املبلــغ‪ ،‬ومبــا َّ‬\n     ‫بعــد ثبــوت احلقــوق؛ لــذا كلــه فقــد ألزمــت املدعــى عليــه ‪ ...‬بدفــع مبلــغ‬\n     ‫ـال للمدعــي‪ ،‬وبــه‬   ‫ألفــا وســبعمائة وخمســون ريـ ً‬   ‫قــدره اثنــان وأربعــون ً‬\n     ‫حكمـ ُـت‪ .‬وبعــرض احلكــم علــى املدعــى عليــه بواســطة املترجــم‪ ،‬قــرر‬\n     ‫عــدم قناعتــه بــه وطلــب رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n     ‫لتدقيــق احلكــم دون الئحــة اعتراضيــة‪ ،‬وأقفلــت اجللســة الســاعة الثالثة‪.‬‬\n     ‫وص َّلــى اهلل وسـلَّم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ُ .‬حــرر‬\n                                                                    ‫يف ‪1433/9/18‬ه‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‪ ،‬ففــي‬\n     ‫يــوم الثالثــاء ‪1433/11/16‬ه ـ فتحــت اجللســة وقــد عــادت املعاملــة مــن‬\n     ‫محكمة االســتئناف باملنطقة الشــرقية مبوجب خطاب فضيلة رئيســها‬\n     ‫مرفقــا بهــا قــرار‬\n                     ‫ً‬       ‫ذي الرقــم ‪ 331760468‬والتاريــخ ‪1433/11/02‬ه ـ‬\n     ‫أصحــاب الفضيلــة قضــاة الدائــرة احلقوقيــة الثانيــة رقــم ‪33434367‬‬\n     ‫نصــه‪ :‬وبدراســة القــرار وصــورة‬     ‫وتاريــخ ‪1433/10/22‬ه ـ املتضمــن مــا ُّ‬\n     ‫ضبطــه وأوراق املعاملــة فقــد لوحــظ أن فضيلتــه حكــم باملبلــغ للمدعــي‬\n\n\n‫‪63‬‬\n\f‫مــع أن املصــاب هــو ابنــه القاصــر‪ ،‬فعلــى فضيلــة القاضــي مالحظــة‬\n‫مــا ذكــر وإكمــال مــا يلــزم نحــوه واهلل املوفــق عليــه أجيــب ألصحــاب‬\n‫الفضيلــة بــأن احلكــم إمنــا هــو البــن املدعــي القاصــر وقــد وقــع احلكــم‬\n‫ـابقا‪ ،‬وألزمــت‬ ‫ـهوا‪ .‬وعليــه‪ ،‬فقــد رجعــت عمــا حكمــت بــه سـ ً‬   ‫لوالــده سـ ً‬\n‫ألفا وســبعمائة وخمســون‬    ‫املدعــى عليــه بدفــع مبلــغ وقــدره اثنــان وأربعون ً‬\n‫ـال وبــه حكمــت‪ ،‬وأمــرت بالتهميــش علــى الصــك مبــا طــرأ عليه ومن‬         ‫ريـ ً‬\n‫ثــم رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‪،‬‬\n‫وأقفلــت اجللســة الســاعة الثانيــة عشــرة ظهـ ًـرا‪ ،‬وصلــى اهلل وس ـلّم علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حتريـ ًـرا يف ‪1433/11/16‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‪ ،‬ففــي‬\n‫يــوم األحــد ‪1434/01/18‬ه ـ فتحــت اجللســة الثالثــة الســاعة الواحــدة‬\n‫والنصــف ظهـ ًـرا وقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم ‪332141980‬‬\n‫مرفقــا بهــا قــرار أصحــاب الفضيلــة قضــاة‬‫ً‬      ‫والتاريــخ ‪1434/01/10‬ه ـ‬\n‫الدائــرة احلقوقيــة الثانيــة رقــم ‪/34606‬ق‪ 2‬وتاريــخ ‪1434/01/03‬ه ـ‬\n‫نصــه‪ :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‪،‬‬      ‫املتضمــن مــا ُّ‬\n‫قررنــا املصادقــة علــى احلكــم وبــاهلل التوفيــق‪ .‬قاضــي اســتئناف ‪.........‬‬\n‫ختمــه وتوقيعــه‪ ،‬قاضــي اســتئناف ‪ ......‬ختمــه وتوقيعــه‪ ،‬رئيــس الدائــرة‬\n‫‪ .....‬ختمــه وتوقيعــه ا‪.‬هــ‪ ،‬وجــرى إثبــات ذلــك اســتنا ًدا إلــى املــادة‬\n‫(‪ ،)3/188‬وأقفلــت اجللســة ‪ ،‬وصلــى اهلل وس ـلّم علــى نبينــا محمــد‬\n            ‫وعلــى آلــه وصحبــه أجمعــن‪ .‬حتريـ ًـرا يف ‪1434/01/18‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬فلــدي أنــا القاضــي باحملكمــة اجلزئيــة‬\n‫باألحســاء فتحــت اجللســة الرابعــة وقــد عــادت إلينــا املعاملــة مــن مديــر‬\n\n\n                                                                                       ‫‪64‬‬\n\f     ‫شــعبة تنفيــذ األحــكام برقــم ‪ 5139‬تاريــخ ‪1434/03/04‬ه ـ واملقيــدة‬\n     ‫باحملكمــة برقــم ‪ 33799075‬واملرفــق بهــا الشــيك رقــم ‪033987‬‬\n     ‫وتاريــخ ‪1434/03/03‬ه ـ املســحوب علــى البنــك ‪ ........‬مببلــغ‪) )25000‬‬\n     ‫ريــال وحضــر لــدي املدعــي واليــة ‪ ........‬ســعودي بالســجل املدنــي رقــم‬\n     ‫(‪ )........‬وجــرى تســليمه الشــيك املذكــور أعــاه وقــرر قائـ ًـا‪ :‬إننــي‬\n     ‫متنــازل عــن باقــي املبلــغ احملكــوم لــي بــه هكــذا قــرر‪ ،‬وعليــه جــرى‬\n     ‫التوقيــع وأمــرت بالتهميــش علــى صكــه مبــا طــرأ عليــه‪ ،‬وأقفلــت‬\n     ‫اجللســة الســاعة الواحــدة والربــع‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                       ‫آلــه وصحبــه وســلم‪ُ .‬حــرر يف تاريــخ ‪1434/03/08‬ه ـ ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"d881bb7a-4fd7-5070-860e-eb0611a9c51d","source_page_start":45,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9e1fd0bbc97e3ea6d8b491870cc769a8f33694158d84a9ae8445cd7d6120a38e","normalized_text_hash":"9a9b47025c91f5e677520c52d41dba177acc983d306b81327ccc0d27cafccc04","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v14-p45-3452286"},{"id":"934eb688-68b4-52bf-90d1-6893009eb1c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"أ ر ش إصاب ة -ا نق اب س يار ة وتس ب ب يف إصاب ة -إيجابي ة ال تقري ر ف ليم نص املد عى علي ه بتس اج -إلزا م للمدع ي-تقدي ر ش ج الطب ي","document_number":"3410235","case_number":"33492631","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"أ ر ش إصاب ة -ا نق اب س يار ة وتس ب ب يف إصاب ة -إيجابي ة ال تقري ر ف ليم نص املد عى علي ه بتس اج -إلزا م للمدع ي-تقدي ر ش ج الطب ي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/1/12 :‬هـ‬\n               ‫ُ‬                    ‫َر ْق ُم َّ‬\n                       ‫الص ِّك‪3410235 :‬‬\n                     ‫الدعوى‪33492631 :‬‬   ‫َر ْق ُم َّ‬\n       ‫ِ‬\n      ‫االستئناف‪:‬‬ ‫صديق من محكم ِة‬\n                             ‫ِ‬      ‫قَ را ِر ال َّت‬\n     ‫تاريخه‪1434/4/16 :‬هـ‬‫ُ‬  ‫َر ْق ُم ‪34189757‬‬\n\n\n\n                                                                   ‫َأ ْر ُش ِإصاب ـةٍ‪ -‬ا ْنقـ ُ‬\n‫ـاب سـ َّـيار ٍة وتسـ َّـب َب يف إصاب ـةٍ‪ -‬إيجابي ـ ُة ال َّتقري ـ ِر‬\n‫ـف‬ ‫ـليم نصـ ِ‬‫املد َعــى علي ـ ِه بتسـ ِ‬\n                                   ‫اج‪ -‬إلــزا ُم َّ‬‫للمدعِ ي‪-‬تقديـ ُـر ِشـ َـج ٍ‬‫َّ‬          ‫الطبـ ِّـي‬\n                                                                ‫للمدعِ ــي‪.‬‬\n                                                                       ‫َّ‬   ‫ـقد ِر‬‫رش امل ُـ َّ‬  ‫ا َأل ِ‬\n\n\n\n\n          ‫القاعِ ــد ُة الفقهيــة‪(( :‬إ َذا اجتمـ َـع املباشـ ُـر واملتسـ ِّـب ُب فـ َّ‬\n‫ـإن احلكـ َـم‬                                                                       ‫‪َ -1‬‬\n                                                             ‫ـاف إلــى املباش ـ ِر))‪،‬‬\n                                                                                   ‫ُيضـ ُ‬\n                  ‫يتعمدْ ))‪.‬‬\n                          ‫َّ‬    ‫لم‬     ‫((املباشر ضامِ ٌن ْ‬\n                                    ‫وإن ْ‬           ‫ُ‬           ‫القاعد ُة الفقهية‪:‬‬   ‫‪َ -2‬‬\n\n\n\n\n‫املد َعــى علي ـ ِه وقـ َـع‬    ‫املدعِ ــي بأ َّن ـ ُه يف أثنــا ِء ركو ِبــه سـ َّـيار ًة بقيــاد ِة َّ‬  ‫ا َّد َعــى َّ‬\n‫املركب ـةِ‪ ،‬وهـ َـو َمــا تسـ َّـب َب‬     ‫َ‬           ‫ـاب‬\n                                                      ‫ـروري جنـ َـم عن ـ ُه انقـ ُ‬     ‫ٌّ‬       ‫ِث ُمـ‬‫لهمــا حــاد ٌ‬ ‫َ‬\n‫املد َعــى علي ـ ِه‬    ‫يف إصاب ِتــه باإلصاب ـ ِة املوصوف ـ ِة يف دعـ َـو ُاه‪ ،‬وقَ ــد ُأديـ َـن َّ‬\n‫املد َعــى علي ـ ِه‬  ‫ـزام َّ‬  ‫فقــد طلـ َـب إلـ َ‬    ‫بنســب ِة ‪ %50‬مـ َـن اخلط ـ ِأ يف احلــاد ِِث؛ لـ َـذا َ‬\n‫الدعـ َـوى‪ُ ،‬جملـ ًة‬        ‫ـاء يف َّ‬‫املد َعــى عليـ ِه مبــا جـ َ‬    ‫أرش إصاب ِتــه‪ -‬أقـ َّـر َّ‬    ‫بتســليمِ ه َ‬\n‫ـاص بإصاب ـ ِة‬     ‫و َت ْفصيـ ًـا‪ ،‬واطلعـ ِـت احملكم ـ ُة ع َلــى ال َّتقريـ ِـر الطبـ ِّـي اخلـ ِّ‬\n‫املد َعى‬ ‫ـجاج باحملكمـةِ‪َّ ..‬‬          ‫الشـ ِ‬   ‫اطلعـ ْـت ع َلــى َتقديـ ِـر ُمقـ ِّـد ِر ِّ‬‫كمــا َ‬ ‫املدعِ ــي‪َ ،‬‬      ‫َّ‬\n‫يتعمــدْ ‪ -‬قضـ ِـت‬       ‫الدعـ َـوى‪ ،‬واملباشـ ُـر ضامِ ـ ٌـن وإنْ لـ ْـم َّ‬       ‫ـاء يف َّ‬  ‫عليـ ِه أقـ َّـر مبــا جـ َ‬\n‫رش اإلصابـ ِة املقـ َّـد ِر مِ ــن‬      ‫ـف َأ ِ‬   ‫ـليم نصـ ِ‬‫املد َعــى عليـ ِه بتسـ ِ‬     ‫ـزام َّ‬\n                                                                                               ‫احملك ُمــة بإلـ ِ‬\n                                                                                                                            ‫‪66‬‬\n\f     ‫واملد َعــى عليـ ِه ع َلــى ا ُحلكـ ِـم‪،‬‬\n                                         ‫املدعِ ــي َّ‬ ‫ض َّ‬       ‫للمدعِ ــي‪ ،‬عـ َ‬\n                                                               ‫ـار َ‬          ‫ـجاج َّ‬\n                                                                                   ‫الشـ ِ‬\n                                                                                      ‫ُمقـ ِّـد ِر ِّ‬\n                                                                                         ‫وقـ ْ‬\n                                                                    ‫ـررت محكم ـ ُة االسـ ِ‬\n                             ‫ـتئناف امل ـ ُـصادق َة ع َلــى ا ُحلكـ ِـم‪.‬‬\n\n\n\n     ‫ـدي أنــا املــازم القضائــي يف احملكمــة‬\n                                           ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n     ‫ـاء علــى املعاملــة‬\n                      ‫اجلزئيــة باألحســاء يف املكتــب القضائــي الســادس‪ ،‬وبنـ ً‬\n     ‫احملالــة لنــا مــن رئيــس احملكمــة اجلزئيــة باألحســاء برقــم ‪33492631‬‬\n     ‫يف ‪1433/7/28‬ه ـ واملقيــدة برقــم ‪ 33142396‬يف ‪1433/7/28‬ه‪،‬ـ‬\n     ‫ـاء علــى اعتمــادي قِ بــل فضيلــة الشــيخ ‪ ...... /‬القاضــي باحملكمــة‬     ‫وبنـ ً‬\n     ‫اجلزئيــة مبحافظــة األحســاء لنظــر هــذه القضيــة‪ ..‬أنــه يف يــوم اإلثنــن‬\n     ‫‪1434/1/12‬هـ ـ افتتحــت اجللســة األولــى يف متــام الســاعة التاســعة والربع‬\n     ‫صباحــا‪ ،‬وفيهــا حضــر املدعــي ‪ ....‬باكســتاني اجلنســية مبوجــب اإلقامــة‬‫ً‬\n     ‫الصــادرة عــن جنــران برقــم ‪ ...‬وحضــر حلضــوره‪ ....‬مينــي اجلنســية مبوجــب‬\n     ‫اإلقامــة الصــادرة مــن جــوازات حرميــاء برقــم ‪ ....‬وحضــر حلضورهمــا‬\n     ‫املترجــم ‪ ...‬هنــدي مبوجــب اإلقامــة رقــم (‪ )...‬وبســؤال املدعــي بواســطة‬\n     ‫املترجــم عــن دعــواه‪ ،‬قــال إنــه بتاريــخ ‪1432/12/24‬ه ويف حوالــي‬\n     ‫صباحــا وقــع حــادث انقــاب‬\n                                ‫ً‬       ‫الســاعة السادســة وخمــس وأربعــن دقيقــة‬\n     ‫علــى طريــق الريــاض تقاطــع ‪ ........‬ملركبــة مــن نــوع ‪ ........‬بكــب إنتــاج‬\n     ‫(‪2008‬م) رقــم اللوحــة (‪ ).......‬بقيــادة املدعــى عليــه هــذا احلاضــر معــي‬\n     ‫وكنــت أنــا برفقتــه‪ ،‬وجنـ َـم عــن حــادث انقــاب مركبــة املدعــى عليــه‬\n     ‫إصابتي بكســر يف الفخذ األيســر الثلث املتوســط وكســر يف املشــيطة‬\n     ‫الرابعــة لليــد اليســرى‪ ،‬وحيــث إن املدعــى عليــه ُأديــن بنســبة ‪%50‬؛ لــذا‬\n     ‫أطلــب إلزامــه بدفــع أرش إصابتــي‪ .‬هــذه دعــواي‪ ،‬وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــال إن مــا ذكــره املدعــي مــن مرافقتــه لــي وركوبــه معــي‬\n‫‪67‬‬\n\f‫يف ســيارتي املوصوفــة يف الدعــوى ووقــوع حــادث االنقــاب مبركبتــي‪،‬‬\n‫ذلــك كلــه صحيــح‪ ،‬وأنــا متســبب يف احلادث بنســبة ‪%50‬؛ هكذا أجاب‬\n‫فتــم اطالعــي علــى القــرار الشــرعي الصــادر عــن احملكمــة اجلزائيــة‬\n‫باألحســاء برقــم (‪ )33289284‬يف‪1433/6/9‬هــ‪ ،‬ويتضمــن (إدانــة‬\n‫املدعــى عليــه جتــاه حــادث االنقــاب املذكــور بنســبة ‪ %50‬للحــق العــام)‬\n‫ا‪.‬هـ ــ‪ ،‬كمــا مت اطالعــي علــى التقريــر الطبــي الصــادر عــن مستشــفى‬\n‫امللك فهد باألحساء برقم ‪ 41/27/4/14795‬يف ‪1433/11/8‬هـ املرفق‬\n‫يف املعاملــة علــى اللفــة رقــم (‪ )92‬واملتضمــن (إصابــة املدعــي بكســر‬\n‫بالفخــذ األيســر الثلــث املتوســط نســبة العجــز تقديريــا ‪ %30‬وكســر‬\n‫املشــيطة الرابعــة لليــد اليســرى نســبة العجــز تقديريــا ‪ %2‬مجمــوع نســب‬\n‫العجــز التقديــري ‪ .%32‬أعضــاء اللجنــة الطبيــة احملليــة استشــاري عظــام‬\n‫د‪ ..... .‬استشاري طب التأهيل د‪ .... .‬رئيس اللجنة الطبية احمللية د‪).......‬‬\n‫ا‪.‬هــ‪ ،‬كمــا متــت الكتابــة ملقــدر الشــجاج لتقديــر أرش إصابــة املدعــي‬\n‫مبوجــب خطابنــا رقــم ‪ 331505157‬يف ‪1433/8/21‬ه ـ وقــد ورد اجلواب‬\n‫برقــم (‪ )....‬يف ‪1433/11/29‬ه ـ واملتضمــن (إصابــة املدعــي بكســر‬\n‫بالفخــذ األيســر الثلــث األوســط وعجــزه ‪ %30‬فيــه خمســة وأربعــون ألــف‬\n‫وأيضــا كســر يف املشــيطة الرابعــة اليســرى فيــه ثالثــة آالف‬        ‫ً‬       ‫ريــال‪،‬‬\n‫ريــال فيكــون مجموعــه ثمانيــة وأربعــن ألــف ريال)ا‪.‬هــ‪ ،‬وبعرضــه علــى‬\n‫املدعــي قــال أنــا مقتنــع بهــذا التقديــر‪ .‬أمــا املدعــى عليــه فقــرر املعارضــة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وحيــث أقــر املدعــى‬     ‫عليــه‪ .‬فبنـ ً‬\n‫عليــه بوقــوع حــادث االنقــاب املوصــوف يف الدعــوى ومرافقــة املدعــي‬\n‫وركوبــه مــع املدعــى عليــه يف ســيارته‪ ،‬وحيــث أديــن املدعــى عليــه يف‬\n‫القــرار الشــرعي بنســبة ‪ %50‬وللقاعــدة الشــرعية ((إذا اجتمــع املباشــر‬\n\n\n                                                                                           ‫‪68‬‬\n\f     ‫واملتســبب فــإن احلكــم يضــاف إلــى املباشــر)) وللقاعــدة‪(( :‬املباشــر‬\n     ‫ضامــن وإن لــم يتعمــد)) األشــباه والنظائــر البــن جنيــم (ص‪،)135‬‬\n     ‫وشــرح القواعــد الفقهيــة ألحمــد الزرقــا(‪ ،)453-447‬واملدخــل الفقهــي‬\n     ‫العــام ملصطفــى الزرقــا (‪ .)1047-1045/2‬وبعــد االطــاع علــى القــرار‬\n     ‫الشــرعي والتقريــر الطبــي وخطــاب مقــدر الشــجاج؛ لذلــك كلــه فقــد‬\n     ‫ـدي أن بذمــة املدعــى عليــه للمدعــي مبل ًغــا وقــدره أربعــة وعشــرون‬\n                                                                           ‫ثبــت لـ ّ‬\n     ‫ألــف ريــال أرش اإلصابــات يلــزم املدعــى عليــه دفعهــا للمدعــي ومبــا‬\n     ‫ســبق حكمــت‪ .‬وبعرضــه علــى املدعــي قــرر معارضتــه علــى احلكــم‪،‬‬\n     ‫كمــا قــرر املدعــى عليــه املعارضــة عليــه وأفهمتهمــا مبراجعــة احملكمــة‬\n     ‫بعــد عشــرة أيــام الســتالم صــورة مــن احلكــم ‪.‬واختتمــت اجللســة يف متــام‬\n     ‫العاشــرة صباح ـ ًا وللبيــان ُحــرر يف ‪1434/1/12‬هــ‪ ،‬وصلــى اهلل علــى‬\n                                          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫احلمــد هلل وحــده‪ ،‬ويف يــوم الثالثــاء املوافــق ‪1434/5/28‬ه ـ ـ افتتحــت‬\n     ‫اجللســة يف متــام الســاعة الثانيــة عشــرة يف الدعــوى املقدمــة مــن ‪ .....‬يف‬\n     ‫دعــوى أرش جنايــة فيمــا دون ثلــث الديــة‪ ،‬وفيهــا حضــر املدعــي ‪.......‬‬\n     ‫باكســتاني اجلنســية مبوجــب اإلقامــة الصــادرة عــن جنــران برقــم (‪).....‬‬\n     ‫وجــرى تســليمه الشــيك املســحوب علــى البنــك ‪ ........‬برقــم (‪)034550‬‬\n     ‫يف ‪1434/5/25‬ه ـ مببلــغ وقــدره أربعــة وعشــرون ألــف ريــال‪ ،‬وقــرر‬\n     ‫قائـ ًـا إنــي بتســليمي لهــذا الشــيك ال أطالــب املدعــى عليــه بخصــوص‬\n     ‫هــذه الدعــوى بــأي شــيء فأثبــت ذلــك‪ .‬وللبيــان ُحــرر يف ‪1434/5/28‬ه ـ‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n     ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34189757‬وتاريــخ‪:‬‬\n                                                                ‫‪1434/4/16‬هـ‬\n\n\n‫‪69‬‬\n\f‫تاريخه‪1434/7/19 :‬هـ‬‫ُ‬  ‫الص ِّك‪34274115 :‬‬   ‫َر ْق ُم َّ‬\n                     ‫عوى‪34317863 :‬‬   ‫الد َ‬  ‫َر ْق ُم َّ‬\n     ‫ِ‬\n    ‫االستئناف‪:‬‬ ‫صديق مِ ن محكم ِة‬\n                            ‫ِ‬   ‫َر ْق ُم قرا ِر ال َّت‬\n          ‫تاريخه‪1434/11/2 :‬هـ‬ ‫ُ‬    ‫‪34346840‬‬\n\n\n‫املدعِ ــي بإقامـ ِة‬\n                  ‫ني تسـ َّـب َب يف إصابـةٍ‪ُ -‬مطالبـ ُة َّ‬‫أرش إصابـةٍ‪ -‬طعـ ٌـن بســك ٍ‬       ‫ُ‬\n‫ـض‬  ‫املد َعــى علي ـ ِه بالبعـ ِ‬\n                            ‫ـرار َّ‬ ‫وأرش اإلصاب ـةِ‪ -‬إقـ ُ‬\n                                                        ‫ـجن ِ‬         ‫احلراب ـ ِة ِّ‬\n                    